/**
 * 待办收件箱（Todo Inbox）— Host half。
 *
 * 定位：
 *   user-attention = 传感器 + 人类交互门控 + 最终拒绝
 *   todo-inbox     = 决策收件箱 + 人工复核 + 单次执行
 *
 * 当同一 bundle 的注意力组件（`@local/dsh-user-attention-core`）因为用户暂离/离线
 * 而最终拒绝一次 approval 或 ask_user_question 时，本组件通过
 * `userAttention.onRejection()` 自动把这次决策收进待办。用户回到 DSH 后可以在
 * 右侧栏或输入框高亮条里：
 *
 *   - 批准一次：模型随后调用 `todo_execute(id)`，本插件从来源会话的
 *     `tool/call` 事件里取回原始参数，并用一次性 approval grant 让注意力门控
 *     直接放行，然后以新的 callId 通过 `ctx.tools.execute` 真正执行一次。
 *   - 回答问题：问题不会重放；用户填写的答案保存在待办里，`todo_execute`
 *     只把答案作为工具结果返回给模型。
 *   - 拒绝：待审核待办改为 `rejected`（不删除、不向来源会话注入说明），用户可以
 *     「返回修改」回到 `pending`；`rejected` 只在用户点「应用操作」或 AI 调用
 *     `todo_*` 工具时归档删除。失败待办的拒绝仍保持原有的归档删除行为。
 *   - 分支对话：DSH 从既有会话派生分支时（`session/created` + `header.parentSession` +
 *     `header.isSeeded`），把原会话里 `pending` / `approved` 的待办复制一份到分支
 *     （新 id、新 `sessionId`、`originSessionId` 指回原会话），原会话待办不变；执行时
 *     按 `originSessionId` 回原会话日志取原始调用。
 *   - 危险区「释放并删除待办缓存」（`POST /api/todo-inbox/purge`）：删除 pending / approved /
 *     rejected / failed，**保留** executing / restarting，清空历史、`forkedSessions` 与一次性
 *     approval grants，并立即写回空的 state.json / history.json（文件保留）。
 *
 * 安全边界：
 *   - 只持久化脱敏参数预览 + 参数哈希；完整参数永远只从来源会话日志读取。
 *   - 执行必须发生在原会话（调用 AI 的 session 必须等于待办来源 session）。
 *   - `todo_*` 等元工具标记 review-only，拒绝执行。`restart_dsh_*` 已放开：
 *     真正的重启类工具在执行前落 `restarting` 状态，宿主重启后由 load() 归档为已执行。
 *   - 用户批准后不设过期时间；执行成功或用户拒绝后删除。
 *
 * 本 bundle 不 import 任何 @deepseek-ai/* 包，全部能力从 ctx 取。
 */

import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'

/** 本插件的 Host 依赖；userAttention / connection 都是可选面，用 ctx.inject 动态等待。 */
export const inject = ['tools', 'agents', 'sessions']

/** 持久化文件版本。 */
export const TODO_STATE_VERSION = 1

/** 历史归档文件版本（只读浏览，不参与待办执行）。 */
export const TODO_HISTORY_VERSION = 1

/** 本插件版本；用于在运行中的 Host 里确认 Loader 加载的是哪一份代码。 */
export const PLUGIN_VERSION = '1.5.0'

/** 一次性 approval grant 的有效期：只是覆盖一次工具执行的审批窗口，不用于长期授权。 */
export const TODO_GRANT_TTL_MS = 5 * 60 * 1000

/** 默认配置；全部可在 profile 补丁本行 config 里覆盖。 */
export const DEFAULT_CONFIG = Object.freeze({
  autoEnqueue: true,
  pollIntervalMs: 2000,
  maxTodos: 200,
  home: undefined,
})

/** 所有有界字段的上限；避免第二个持久化文件无限增长。 */
export const TODO_LIMITS = Object.freeze({
  todos: 200,
  titleChars: 160,
  detailChars: 600,
  previewChars: 1000,
  requestReasonChars: 400,
  questionChars: 2000,
  questionDetailChars: 4000,
  headerChars: 200,
  optionLabelChars: 200,
  optionDescriptionChars: 500,
  options: 20,
  questions: 10,
  listLimit: 100,
  toolListLimit: 30,
  outputPreviewChars: 2000,
  failReasonChars: 500,
  batch: 10,
  historyAnswersChars: 600,
  forkedSessions: 100,
})

const TODO_STATUSES = new Set(['pending', 'approved', 'rejected', 'executing', 'restarting', 'failed'])
const TODO_KINDS = new Set(['approval', 'question'])
const REJECTION_REASONS = new Set(['manual', 'offline', 'timeout-manual', 'timeout'])
const HISTORY_OUTCOMES = new Set(['executed', 'rejected', 'failed', 'restarted', 'answered'])

/** 拒绝原因的中文标签（与注意力插件的解释保持一致）。 */
const REASON_LABELS = Object.freeze({
  manual: '用户手动离线',
  offline: '用户离线',
  'timeout-manual': '手动暂离且无人响应',
  timeout: '暂离且提醒后仍无响应',
})

/**
 * 分支对话复制（`session/created` 里 `header.parentSession` + `header.isSeeded`）
 * 只复制这两种状态的待办：还没被用户决定（`pending`）或已被批准/回答（`approved`）。
 * `failed` / `executing` / `restarting` 已经有结果或正在进行，`rejected` 是用户的否决，
 * 复制到分支只会制造歧义。
 */
const FORK_COPY_STATUSES = new Set(['pending', 'approved'])

/**
 * 危险操作「释放并删除待办缓存」必须保留的状态：正在跑原工具的待办不能被打断，
 * 否则用户与模型都失去线索（执行结束后仍走原来的 removeTodo / archiveTodo 路径）。
 */
const PURGE_KEEP_STATUSES = new Set(['executing', 'restarting'])

/**
 * 不可有意义重放的元工具：可以入队供人工复核，但不允许 todo_execute 执行。
 * 这些工具的效果是“改变当前对话/插件状态”或本身就是审批/提问传输层，
 * 重放没有意义、甚至危险。
 */
const REVIEW_ONLY_PATTERNS = Object.freeze([
  /^todo_/,
  /^ask_user_question$/,
  /^workflow$/,
  /^subagent_fork$/,
])

/**
 * 真正会让宿主重启的工具名。`restart_dsh_status` 是只读、`restart_dsh_force_safeguard`
 * 只是给下一次调用上保险，两者都不属于“执行即重启”，不能按 restarting 落盘。
 * 其余 `restart_dsh_*`（blocking_wait_safe / roll_call_caution / force_dangerous）
 * 执行后宿主会消失，所以执行前先持久化 restarting，重启后由 load() 归档。
 */
const RESTART_TOOL_PATTERN = /^restart_dsh_(?!status$|force_safeguard$)/

/** 把任意用户配置收敛成安全值（不信任 YAML 里的类型）。 */
export function normalizeConfig(raw) {
  const input = raw !== null && typeof raw === 'object' ? raw : {}
  const number = (value, fallback, min, max) => {
    const n = Number(value)
    if (!Number.isFinite(n)) return fallback
    return Math.min(max, Math.max(min, n))
  }
  return {
    autoEnqueue: typeof input.autoEnqueue === 'boolean' ? input.autoEnqueue : DEFAULT_CONFIG.autoEnqueue,
    pollIntervalMs: Math.round(number(input.pollIntervalMs, DEFAULT_CONFIG.pollIntervalMs, 1000, 10000)),
    maxTodos: Math.round(number(input.maxTodos, DEFAULT_CONFIG.maxTodos, 10, 1000)),
    home: typeof input.home === 'string' && input.home.trim() !== '' ? input.home : undefined,
  }
}

function uuid() {
  try {
    if (typeof globalThis.crypto?.randomUUID === 'function') return globalThis.crypto.randomUUID()
  } catch (error) { /* 回退到时间戳形式 */ }
  return 'ti-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10)
}

function jsonResponse(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
    },
  })
}

function messageOf(error) {
  return error !== null && error !== undefined && typeof error.message === 'string' ? error.message : String(error)
}

function boundText(value, max) {
  return typeof value === 'string' ? value.slice(0, max) : ''
}

/** 工具名是否属于“仅复核、不可重放”的元工具。 */
export function isReviewOnlyTool(toolName) {
  if (typeof toolName !== 'string' || toolName === '') return false
  return REVIEW_ONLY_PATTERNS.some((pattern) => pattern.test(toolName))
}

/** 稳定参数指纹；只用于校验来源会话日志里的参数没有被改动。 */
export function sha256Hex(value) {
  try {
    return createHash('sha256').update(String(value)).digest('hex')
  } catch {
    return ''
  }
}

const SENSITIVE_ARG_KEY = /(key|token|secret|password|passwd|authorization|cookie|credential)/i

/** 递归脱敏 JSON 值：敏感键一律替换为 [redacted]。 */
function redactJsonValue(value) {
  if (Array.isArray(value)) return value.map((item) => redactJsonValue(item))
  if (value !== null && typeof value === 'object') {
    const output = {}
    for (const [key, item] of Object.entries(value)) {
      output[key] = SENSITIVE_ARG_KEY.test(key) ? '[redacted]' : redactJsonValue(item)
    }
    return output
  }
  return value
}

/** JSON 级脱敏 + 有界预览；永远不保存完整参数。 */
export function redactArgsPreview(raw, maxChars = TODO_LIMITS.previewChars) {
  const limit =
    typeof maxChars === 'number' && Number.isFinite(maxChars) && maxChars > 0
      ? Math.floor(maxChars)
      : TODO_LIMITS.previewChars
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? null)
  let preview = text
  try {
    preview = JSON.stringify(redactJsonValue(JSON.parse(text)))
  } catch {
    preview = text.replace(
      /((?:key|token|secret|password|passwd|authorization|cookie|credential)[A-Za-z0-9_-]*\s*[:=]\s*)("[^"]*"|'[^']*'|[^\s,;]+)/gi,
      '$1[redacted]',
    )
  }
  return preview.length > limit ? `${preview.slice(0, Math.max(1, limit - 1))}…` : preview
}

/**
 * 从会话事件里定位一次工具调用的原始参数。
 * @param events - session.ownEvents() 返回的事件数组
 * @param callId - 目标工具调用 id
 * @returns `{ name, arguments }`，找不到时返回 null
 */
export function findToolCallArguments(events, callId) {
  if (!Array.isArray(events) || typeof callId !== 'string' || callId === '') return null
  let found = null
  for (const event of events) {
    if (event === null || typeof event !== 'object' || event.type !== 'tool/call') continue
    const data = event.data
    if (data === null || typeof data !== 'object') continue
    if (String(data.callId ?? '') !== callId) continue
    found = {
      name: typeof data.name === 'string' ? data.name : '',
      arguments: typeof data.arguments === 'string' ? data.arguments : '',
    }
  }
  return found
}

/**
 * 会被算作「会话已经有对话内容」的事件类型。
 *
 * 只在拿不到 `session.surface` 时作为兜底：`turn/start` 与 DSH 会话列表的
 * `blank` 投影同义（用户发出第一条提示、开启第一轮对话），其余是消息/工具事件。
 * 注意不要用「事件条数 > 0」判断：标题、配置、插件记录等与会话内容无关的事件
 * 也会写进同一个日志，那会把空会话误判成已有内容。
 */
const CONTENT_EVENT_TYPES = Object.freeze([
  'turn/start',
  'user/message',
  'assistant/message',
  'tool/call',
  'tool/result',
])

/**
 * 判断一个活会话是否已经有对话内容（右栏待办面板默认作用域的依据）。
 *
 * 首选 `session.surface.nodes`：DSH 的会话「消息面」只收录会产生模型可见消息的
 * 事件（用户/助手消息、工具结果等），全新会话为空，发出第一条消息后立刻非空。
 * 它随会话对象增量维护，是 O(1) 读，且与标题、待办数量、无关日志事件都无关。
 * surface 不可用（旧版 Session 对象/测试替身）时退回扫描事件类型。
 *
 * @param session - `ctx.sessions.list()` 里的活会话；冷会话没有对象。
 * @returns true=已有内容；false=还没有任何对话内容；null=无法判断（会话不在活列表里）
 */
export function detectSessionHasContent(session) {
  if (session === null || session === undefined || typeof session !== 'object') return null
  try {
    const nodes = session.surface?.nodes
    if (Array.isArray(nodes)) return nodes.length > 0
  } catch (error) { /* surface 不可用时退回事件扫描 */ }
  try {
    if (typeof session.ownEvents === 'function') {
      const events = session.ownEvents()
      if (Array.isArray(events)) {
        return events.some((event) => event !== null && typeof event === 'object' &&
          CONTENT_EVENT_TYPES.includes(event.type))
      }
    }
  } catch (error) { /* 读不到日志时按未知处理 */ }
  return null
}

/** 把注意力插件传来的问题快照再收敛一次，作为第二道信任边界。 */
export function sanitizeTodoQuestions(raw) {
  if (!Array.isArray(raw)) return []
  const questions = []
  for (const item of raw.slice(0, TODO_LIMITS.questions)) {
    if (item === null || typeof item !== 'object') continue
    const id = boundText(item.id, 120)
    const question = boundText(item.question, TODO_LIMITS.questionChars)
    if (id === '' || question === '') continue
    const copy = { id, question }
    const detail = boundText(item.detail, TODO_LIMITS.questionDetailChars)
    if (detail !== '') copy.detail = detail
    const header = boundText(item.header, TODO_LIMITS.headerChars)
    if (header !== '') copy.header = header
    if (Array.isArray(item.options)) {
      const options = []
      for (const option of item.options.slice(0, TODO_LIMITS.options)) {
        if (option === null || typeof option !== 'object') continue
        const label = boundText(option.label, TODO_LIMITS.optionLabelChars)
        if (label === '') continue
        const next = { label }
        const description = boundText(option.description, TODO_LIMITS.optionDescriptionChars)
        if (description !== '') next.description = description
        options.push(next)
      }
      if (options.length > 0) copy.options = options
    }
    if (item.multiSelect === true) copy.multiSelect = true
    const intent = item.intent
    if (intent !== null && intent !== undefined && typeof intent === 'object' && intent.kind === 'plan-review') {
      const approve = boundText(intent.approve, 200)
      if (approve !== '') {
        copy.intent = { kind: 'plan-review', approve }
        if (intent.callId !== undefined && intent.callId !== null) {
          copy.intent.callId = String(intent.callId).slice(0, 200)
        }
      }
    }
    questions.push(copy)
  }
  return questions
}

/**
 * 校验用户对问题的回答。
 * 允许规则：
 *   - 每个问题 id 必须属于原始问题；
 *   - 有 options 时 selected 必须是其中之一的 label；
 *   - 无 options 时允许 selected 为空 + custom 自由文本；
 *   - 自由文本有界；至少给出一个非空答案。
 * @returns `{ ok: true, answers }` 或 `{ ok: false, error }`
 */
export function validateAnswers(questions, rawAnswers) {
  const source = Array.isArray(questions) ? questions : []
  const input = Array.isArray(rawAnswers) ? rawAnswers : []
  if (source.length === 0) return { ok: false, error: '该待办没有可回答的问题' }
  const byId = new Map(source.map((question) => [question.id, question]))
  const answers = []
  for (const item of input) {
    if (item === null || typeof item !== 'object') return { ok: false, error: '答案格式无效' }
    const id = typeof item.id === 'string' ? item.id : ''
    const question = byId.get(id)
    if (question === undefined) return { ok: false, error: '答案引用了不存在的问题：' + id }
    const selected = []
    if (Array.isArray(item.selected)) {
      for (const label of item.selected) {
        if (typeof label !== 'string' || label === '') return { ok: false, error: '选项答案必须是非空字符串' }
        const allowed = Array.isArray(question.options) && question.options.some((option) => option.label === label)
        if (Array.isArray(question.options) && question.options.length > 0 && !allowed) {
          return { ok: false, error: '答案包含问题没有的选项：' + label }
        }
        selected.push(label.slice(0, 500))
      }
    }
    if (!question.multiSelect && selected.length > 1) {
      return { ok: false, error: '该问题只能选择一个选项' }
    }
    const custom = boundText(item.custom, 4000)
    if (selected.length === 0 && custom === '') {
      return { ok: false, error: '问题 ' + id + ' 还没有答案' }
    }
    const answer = { id, selected }
    if (custom !== '') answer.custom = custom
    answers.push(answer)
  }
  for (const question of source) {
    if (!answers.some((answer) => answer.id === question.id)) {
      return { ok: false, error: '问题 ' + question.id + ' 还没有答案' }
    }
  }
  return { ok: true, answers }
}

/**
 * 校验「拒绝时提交的草稿答案」：比 `validateAnswers` 宽松——允许某题还没答
 * （`selected` 与 `custom` 都为空），允许只提交一部分问题，用于把用户点「拒绝」
 * 那一刻的表单状态存进 `todo.answers`，供「已操作」只读展示与「返回修改」预填。
 * 仍然校验：答案必须引用真实问题、选项必须是该题已有 label、单选只能选一个、
 * 自由文本有界。
 * @returns `{ ok: true, answers: [{ id, selected, custom? }] }` 或 `{ ok: false, error }`
 */
export function validateDraftAnswers(questions, rawAnswers) {
  const source = Array.isArray(questions) ? questions : []
  const input = Array.isArray(rawAnswers) ? rawAnswers : []
  if (source.length === 0) return { ok: true, answers: [] }
  const byId = new Map(source.map((question) => [question.id, question]))
  const answers = []
  const seen = new Set()
  for (const item of input) {
    if (item === null || typeof item !== 'object') return { ok: false, error: '答案格式无效' }
    const id = typeof item.id === 'string' ? item.id : ''
    const question = byId.get(id)
    if (question === undefined) return { ok: false, error: '答案引用了不存在的问题：' + id }
    if (seen.has(id)) return { ok: false, error: '答案包含重复的问题：' + id }
    seen.add(id)
    const selected = []
    if (Array.isArray(item.selected)) {
      for (const label of item.selected) {
        if (typeof label !== 'string' || label === '') return { ok: false, error: '选项答案必须是非空字符串' }
        const hasOptions = Array.isArray(question.options) && question.options.length > 0
        const allowed = hasOptions && question.options.some((option) => option.label === label)
        if (hasOptions && !allowed) {
          return { ok: false, error: '答案包含问题没有的选项：' + label }
        }
        selected.push(label.slice(0, 500))
      }
    }
    if (!question.multiSelect && selected.length > 1) {
      return { ok: false, error: '该问题只能选择一个选项' }
    }
    const custom = boundText(item.custom, 4000)
    const answer = { id, selected }
    if (custom !== '') answer.custom = custom
    answers.push(answer)
  }
  return { ok: true, answers }
}

/**
 * 草稿答案（pending/rejected）只做宽松校验；只有真正要交给模型执行的
 * `approved`（以及过渡中的 executing/restarting）才用严格校验，避免半截草稿
 * 在重新加载后把可执行答案清空、或让不完整答案被当作用户答复返回给模型。
 */
function validateStoredAnswers(status, questions, rawAnswers) {
  if (status === 'approved' || status === 'executing' || status === 'restarting') {
    return validateAnswers(questions, rawAnswers)
  }
  return validateDraftAnswers(questions, rawAnswers)
}

/**
 * 有些工具（如 `plugin_manager`）把业务失败放在**成功**的工具结果值里
 * （`application: 'failed'` / `error: { code }` / `ok: false`）。todo_execute
 * 不能只看 `isError`，否则会把“已经装过、这次什么都没做”误判为执行成功并删除待办。
 * @returns 失败说明，或 null 表示没有检测到失败。
 */
export function detectToolValueFailure(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return null
  const record = value
  const applicationFailed = record.application === 'failed'
  const okFalse = record.ok === false
  if (!applicationFailed && !okFalse) return null
  let code
  let detail
  if (record.error !== null && typeof record.error === 'object' && !Array.isArray(record.error)) {
    code = typeof record.error.code === 'string' ? record.error.code : undefined
    detail = typeof record.error.message === 'string' ? record.error.message : undefined
  } else if (typeof record.error === 'string') {
    detail = record.error
  }
  if (detail === undefined && typeof record.message === 'string' && record.message !== '') detail = record.message
  if (code !== undefined && detail !== undefined) return code + ': ' + detail
  if (code !== undefined) return code
  return detail !== undefined ? detail : '工具返回了失败结果'
}

/**
 * 命令类工具（pwsh/bash）把**非零退出码当作正常结果**返回（`isError === false`），
 * 渲染里只带 `[exit code: N]` 明细。todo_execute 如果只看 `isError`，会把“命令失败”
 * 误判为执行成功并删除待办。这里读取前台结果值里的 exitCode/signal/timedOut/aborted/
 * stopped，并用内容里的 exit-code 标记兜底。
 * @returns 失败说明，或 null 表示命令正常完成。
 */
export function detectProcessFailure(value, contentText) {
  const structured = value !== null && typeof value === 'object' && !Array.isArray(value)
  if (structured) {
    if (value.kind === 'foreground') {
      if (typeof value.exitCode === 'number' && value.exitCode !== 0) {
        return '命令退出码 ' + String(value.exitCode)
      }
      if (typeof value.signal === 'string' && value.signal !== '') {
        return '命令被信号终止：' + value.signal
      }
      if (value.timedOut === true) return '命令超时'
      if (value.aborted === true) return '命令被中断'
      if (typeof value.stopped === 'string' && value.stopped !== '') {
        return '命令停止：' + value.stopped
      }
    }
    return null
  }
  if (typeof contentText === 'string') {
    const match = /\[exit code:\s*(\d+)\]/.exec(contentText)
    if (match !== null && Number(match[1]) !== 0) {
      return '命令退出码 ' + match[1]
    }
  }
  return null
}

/**
 * `todo_execute` 的模型可见文本：必须把工具执行结果预览或用户答案带上，
 * 否则模型只能看到“已执行”的空壳，拿不到要继续工作所需的信息。
 */
export function renderTodoExecuteText(value) {
  const lines = []
  const message = value !== null && typeof value === 'object' && typeof value.message === 'string' ? value.message : ''
  if (message !== '') lines.push(message)
  if (value !== null && typeof value === 'object' && typeof value.outputPreview === 'string' && value.outputPreview.trim() !== '') {
    lines.push('执行结果预览：\n' + value.outputPreview)
    lines.push('（只显示有界预览；完整输出请查看工具自身的会话记录或 UI 卡片。）')
  }
  if (value !== null && typeof value === 'object' && Array.isArray(value.answers) && value.answers.length > 0) {
    lines.push('用户答案：' + JSON.stringify(value.answers))
  }
  if (lines.length === 0) return JSON.stringify(value)
  return lines.join('\n\n')
}

/** 工具结果 content 拍平后有界文本。 */
export function flattenContent(content, maxChars = TODO_LIMITS.outputPreviewChars) {
  if (!Array.isArray(content)) return ''
  const parts = []
  for (const block of content) {
    if (block === null || typeof block !== 'object') continue
    if (block.type === 'text' && typeof block.text === 'string') parts.push(block.text)
  }
  const text = parts.join('\n').trim()
  return text.length > maxChars ? `${text.slice(0, Math.max(1, maxChars - 1))}…` : text
}

/** 参数里常见的“文件位置”键名；只收集这些键，避免把任意字符串误当路径。 */
const FILE_KEYS = new Set([
  'file_path', 'filePath', 'path', 'cwd', 'workdir', 'target', 'files', 'file', 'paths',
  'notebook_path', 'notebookPath',
])

/** 判断一个字符串是否像文件路径（绝对路径或带分隔符的相对路径）。 */
function looksLikePath(value) {
  if (typeof value !== 'string' || value === '' || value.length > 500) return false
  return /^[A-Za-z]:[\\/]/.test(value) || value.startsWith('/') || value.startsWith('\\\\') ||
    value.includes('/') || value.includes('\\')
}

/**
 * 从原始工具参数里收集引用文件路径（用于待办卡片上的“打开引用文件”入口）。
 * 只做浅层键名匹配，永不解析执行内容；最多返回 8 条。
 */
export function collectReferencedFiles(rawArgs) {
  let value = rawArgs
  if (typeof rawArgs === 'string') {
    try {
      value = JSON.parse(rawArgs)
    } catch {
      return []
    }
  }
  const files = []
  const seen = new Set()
  const visit = (node, depth) => {
    if (node === null || node === undefined || depth > 3 || files.length >= 8) return
    if (typeof node === 'string') return
    if (Array.isArray(node)) {
      for (const item of node.slice(0, 20)) visit(item, depth + 1)
      return
    }
    if (typeof node !== 'object') return
    for (const [key, item] of Object.entries(node)) {
      if (FILE_KEYS.has(key)) {
        if (typeof item === 'string') {
          if (looksLikePath(item) && !seen.has(item)) {
            seen.add(item)
            files.push(item.slice(0, 500))
          }
        } else if (Array.isArray(item)) {
          for (const candidate of item.slice(0, 20)) {
            if (typeof candidate === 'string' && looksLikePath(candidate) && !seen.has(candidate)) {
              seen.add(candidate)
              files.push(candidate.slice(0, 500))
            } else if (candidate !== null && typeof candidate === 'object' && typeof candidate.path === 'string' &&
              looksLikePath(candidate.path) && !seen.has(candidate.path)) {
              seen.add(candidate.path)
              files.push(candidate.path.slice(0, 500))
            }
          }
        }
      } else if (item !== null && typeof item === 'object') {
        visit(item, depth + 1)
      }
      if (files.length >= 8) return
    }
  }
  visit(value, 0)
  return files
}

/** 标题/详情的人类可读构造（纯函数便于测试）。 */
export function describeRejection(kind, toolName, reason, sessionId) {
  const reasonLabel = REASON_LABELS[reason] ?? REASON_LABELS.offline
  const sessionLabel = typeof sessionId === 'string' && sessionId !== '' ? sessionId.slice(0, 8) : '未知'
  if (kind === 'question') {
    return {
      title: '回答 AI 的提问（' + reasonLabel + '）',
      detail:
        'AI 在会话 ' + sessionLabel + ' 中向你提问；因为' + reasonLabel +
        '，这次提问被自动拒绝并存入待办。原始问题已保留，你回答后由模型调用 todo_execute 取回答案（不会重放 ask_user_question）。',
    }
  }
  const toolLabel = typeof toolName === 'string' && toolName !== '' ? toolName : '未知工具'
  return {
    title: '批准 ' + toolLabel + '（' + reasonLabel + '）',
    detail:
      'AI 在会话 ' + sessionLabel + ' 中请求批准执行 ' + toolLabel + '；因为' + reasonLabel +
      '，这次请求被自动拒绝并存入待办。批准后模型可在来源会话中通过 todo_execute 执行一次；执行前会校验会话日志里的原始参数。',
  }
}

/**
 * 由一次拒绝事件 + 会话日志中的原始调用构造待办记录。
 * @param input - `{ id, event, call, now }`；call 可为 null（日志暂时不可读）
 * @returns 待办记录，或 `{ skipped: reason }`
 */
export function createTodoRecord(input = {}) {
  const event = input.event !== null && typeof input.event === 'object' ? input.event : {}
  const kind = TODO_KINDS.has(event.kind) ? event.kind : null
  if (kind === null) return { skipped: 'invalid-kind' }
  const sessionId = typeof event.sessionId === 'string' && event.sessionId !== '' ? event.sessionId : ''
  if (sessionId === '') return { skipped: 'missing-session' }
  const reason = REJECTION_REASONS.has(event.reason) ? event.reason : 'offline'
  const now = typeof input.now === 'number' && Number.isFinite(input.now) ? input.now : Date.now()
  const toolName =
    kind === 'approval' && typeof event.toolName === 'string' && event.toolName !== ''
      ? event.toolName.slice(0, 160)
      : null
  const callId =
    typeof event.callId === 'string' && event.callId !== '' ? event.callId.slice(0, 200) : null
  const call = input.call !== null && typeof input.call === 'object' ? input.call : null
  const argsText = call !== null && typeof call.arguments === 'string' ? call.arguments : null
  const referencedFiles = argsText === null ? [] : collectReferencedFiles(argsText)
  const reviewOnly = kind === 'approval' ? toolName === null || isReviewOnlyTool(toolName) : false
  const description = describeRejection(kind, toolName, reason, sessionId)
  const detail = reviewOnly
    ? description.detail + ' 该工具标记为仅复核，不能通过 todo_execute 执行，只能拒绝或删除。'
    : description.detail
  const record = {
    id: typeof input.id === 'string' && input.id !== '' ? input.id : 'todo-' + now.toString(36) + '-' + Math.random().toString(36).slice(2, 8),
    status: 'pending',
    kind,
    source: 'attention',
    sessionId: sessionId.slice(0, 200),
    // 复制到分支对话的待办会指回原会话；本会话里产生的待办没有这个字段。
    originSessionId: null,
    rejectReason: reason,
    reviewOnly,
    title: description.title.slice(0, TODO_LIMITS.titleChars),
    detail: detail.slice(0, TODO_LIMITS.detailChars),
    createdAt: now,
    decidedAt: null,
    executedAt: null,
    toolName,
    callId,
    argsHash: argsText !== null ? sha256Hex(argsText) : null,
    argsPreview: argsText !== null ? redactArgsPreview(argsText) : null,
    referencedFiles,
    requestReason:
      typeof event.requestReason === 'string' && event.requestReason !== ''
        ? event.requestReason.slice(0, TODO_LIMITS.requestReasonChars)
        : null,
    questions: kind === 'question' ? sanitizeTodoQuestions(event.questions) : null,
    answers: null,
    resultSummary: null,
    failReason: null,
  }
  return { todo: record }
}

/** 客户端/模型可见的摘要（不含完整问题、参数、answers）。 */
export function summarizeTodo(todo) {
  if (todo === null || typeof todo !== 'object') return null
  return {
    id: todo.id,
    status: todo.status,
    kind: todo.kind,
    source: todo.source,
    sessionId: todo.sessionId,
    originSessionId: typeof todo.originSessionId === 'string' && todo.originSessionId !== ''
      ? todo.originSessionId
      : null,
    toolName: todo.toolName,
    callId: todo.callId,
    title: todo.title,
    rejectReason: todo.rejectReason,
    reviewOnly: todo.reviewOnly === true,
    createdAt: todo.createdAt,
    decidedAt: todo.decidedAt,
    failed: todo.status === 'failed',
    questionCount: Array.isArray(todo.questions) ? todo.questions.length : 0,
    requestReason: todo.requestReason,
    argsPreview: todo.argsPreview,
    referencedFiles: Array.isArray(todo.referencedFiles) ? todo.referencedFiles : [],
    detail: todo.detail,
  }
}

/** 模型 `todo_get` 的可见投影：保留问题与参数预览，但不暴露答案。 */
export function detailTodo(todo) {
  const summary = summarizeTodo(todo)
  if (summary === null) return null
  return {
    ...summary,
    requestReason: todo.requestReason,
    questions: Array.isArray(todo.questions) ? todo.questions : null,
    resultSummary: todo.resultSummary,
    failReason: todo.failReason,
  }
}

/** 校验并修复持久化文件里的记录（损坏/旧版本一律安全忽略）。 */
export function sanitizeStoredTodo(raw) {
  if (raw === null || typeof raw !== 'object') return null
  const id = typeof raw.id === 'string' && raw.id !== '' ? raw.id : ''
  const kind = TODO_KINDS.has(raw.kind) ? raw.kind : ''
  const sessionId = typeof raw.sessionId === 'string' && raw.sessionId !== '' ? raw.sessionId : ''
  if (id === '' || kind === '' || sessionId === '') return null
  let status = TODO_STATUSES.has(raw.status) ? raw.status : 'failed'
  // Host 在 executing 中间重启：无法知道原工具是否已经产生副作用，保留为 failed 供人工处理。
  if (status === 'executing') status = 'failed'
  const questions = Array.isArray(raw.questions) ? sanitizeTodoQuestions(raw.questions) : null
  let answers = Array.isArray(raw.answers) ? raw.answers.slice(0, TODO_LIMITS.questions) : null
  // 手工改坏/旧格式的答案不应被 todo_execute 原样返回给模型：重新用问题定义校验。
  // 待审核 / 已拒绝的答案是「草稿」（可能没答完），只有可执行的 approved 才要求完整。
  if (answers !== null && questions !== null) {
    const checked = validateStoredAnswers(status, questions, answers)
    if (checked.ok !== true) answers = null
    else answers = checked.answers
  }
  return {
    id: id.slice(0, 200),
    status,
    kind,
    source: typeof raw.source === 'string' ? raw.source.slice(0, 40) : 'attention',
    sessionId: sessionId.slice(0, 200),
    // 分支复制标记：可选、有界；缺失/损坏一律回退为 null（等价于“就是本会话产生的”）。
    originSessionId: typeof raw.originSessionId === 'string' && raw.originSessionId !== ''
      ? raw.originSessionId.slice(0, 200)
      : null,
    rejectReason: REJECTION_REASONS.has(raw.rejectReason) ? raw.rejectReason : 'offline',
    reviewOnly: raw.reviewOnly === true,
    title: boundText(raw.title, TODO_LIMITS.titleChars) || '待办',
    detail: boundText(raw.detail, TODO_LIMITS.detailChars),
    createdAt: typeof raw.createdAt === 'number' ? raw.createdAt : Date.now(),
    decidedAt: typeof raw.decidedAt === 'number' ? raw.decidedAt : null,
    executedAt: typeof raw.executedAt === 'number' ? raw.executedAt : null,
    toolName: typeof raw.toolName === 'string' && raw.toolName !== '' ? raw.toolName.slice(0, 160) : null,
    callId: typeof raw.callId === 'string' && raw.callId !== '' ? raw.callId.slice(0, 200) : null,
    argsHash: typeof raw.argsHash === 'string' && raw.argsHash !== '' ? raw.argsHash : null,
    argsPreview: typeof raw.argsPreview === 'string' ? raw.argsPreview.slice(0, TODO_LIMITS.previewChars) : null,
    referencedFiles: Array.isArray(raw.referencedFiles)
      ? raw.referencedFiles.filter((item) => typeof item === 'string').slice(0, 8).map((item) => item.slice(0, 500))
      : [],
    requestReason: typeof raw.requestReason === 'string' ? raw.requestReason.slice(0, TODO_LIMITS.requestReasonChars) : null,
    questions,
    answers,
    // 安装/卸载插件会热重载正在执行 todo_execute 的 Host：标记后 load() 不再误判为 failed。
    reloadExpected: raw.reloadExpected === true,
    resultSummary: typeof raw.resultSummary === 'string' ? raw.resultSummary.slice(0, TODO_LIMITS.outputPreviewChars) : null,
    failReason: typeof raw.failReason === 'string' ? raw.failReason.slice(0, TODO_LIMITS.failReasonChars) : null,
  }
}

export function apply(ctx, config) {
  const cfg = normalizeConfig(config)
  const instanceId = uuid()
  const log = (...args) => {
    try { console.log('[todo-inbox]', ...args) } catch (error) { /* 日志不可用不影响功能 */ }
  }
  const safeGet = (name) => {
    try {
      const value = ctx.get(name)
      return value === undefined || value === null ? undefined : value
    } catch (error) {
      return undefined
    }
  }

  // ---------------------------------------------------------------------------
  // home / 持久化文件
  // ---------------------------------------------------------------------------
  function resolveHome() {
    if (cfg.home !== undefined) return cfg.home
    try {
      const profileContext = ctx.get('profileContext')
      if (profileContext !== null && typeof profileContext === 'object' &&
        typeof profileContext.home === 'string' && profileContext.home.trim() !== '') {
        return profileContext.home
      }
    } catch (error) { /* profileContext 不可用时继续回退 */ }
    const envHome = typeof process !== 'undefined' && process.env !== undefined ? process.env.DSH_HOME : undefined
    if (typeof envHome === 'string' && envHome.trim() !== '') return envHome
    return join(homedir(), '.dsh')
  }

  const home = resolveHome()
  const stateDir = join(home, '.dsh-todo-inbox')
  const stateFile = join(stateDir, 'state.json')

  /** 内存中的待办列表，按 createdAt 升序。 */
  let todos = []

  /**
   * 已经处理过「分支复制」的分支会话 id（有界、随 state.json 持久化）。
   *
   * 只靠“分支里有没有待办”不足以判断：复制过去的待办可能已经在分支里执行/拒绝了。
   * 这份记录让同一分支再次触发 `session/created`（例如恢复分支会话、宿主重启）
   * 仍然幂等，不会把原会话的待办重新复制一遍。
   */
  let forkedSessions = []

  /** 历史归档：只读、无上限、按 seq 单调递增；与活动待办分开持久化。 */
  let history = []
  let historySeq = 0

  function persist() {
    const payload = JSON.stringify({ version: TODO_STATE_VERSION, savedAt: Date.now(), todos, forkedSessions })
    const tmpFile = stateFile + '.' + process.pid + '.' + Date.now() + '.tmp'
    try {
      mkdirSync(stateDir, { recursive: true })
      writeFileSync(tmpFile, payload, 'utf8')
      try {
        renameSync(tmpFile, stateFile)
      } catch (error) {
        if (!existsSync(stateFile)) throw error
        writeFileSync(stateFile, payload, 'utf8')
        try { rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 临时文件清理失败可忽略 */ }
      }
    } catch (error) {
      try { if (existsSync(tmpFile)) rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 同上 */ }
      log('could not persist state:', messageOf(error))
    }
  }

  const historyFile = join(stateDir, 'history.json')

  function persistHistory() {
    const payload = JSON.stringify({ version: TODO_HISTORY_VERSION, savedAt: Date.now(), seq: historySeq, entries: history })
    const tmpFile = historyFile + '.' + process.pid + '.' + Date.now() + '.tmp'
    try {
      mkdirSync(stateDir, { recursive: true })
      writeFileSync(tmpFile, payload, 'utf8')
      try {
        renameSync(tmpFile, historyFile)
      } catch (error) {
        if (!existsSync(historyFile)) throw error
        writeFileSync(historyFile, payload, 'utf8')
        try { rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 临时文件清理失败可忽略 */ }
      }
    } catch (error) {
      try { if (existsSync(tmpFile)) rmSync(tmpFile, { force: true }) } catch (cleanupError) { /* 同上 */ }
      log('could not persist history:', messageOf(error))
    }
  }

  /** 历史里的问题快照：复用问题收敛逻辑，空/无效一律 null。 */
  function historyQuestions(raw) {
    if (!Array.isArray(raw)) return null
    const questions = sanitizeTodoQuestions(raw)
    return questions.length === 0 ? null : questions
  }

  /** 历史里的答案快照：深拷贝为 `{ id, selected, custom? }`，与 validateAnswers 同界。 */
  function historyAnswers(raw) {
    if (!Array.isArray(raw)) return null
    const answers = []
    for (const item of raw.slice(0, TODO_LIMITS.questions)) {
      if (item === null || typeof item !== 'object') continue
      const id = boundText(item.id, 120)
      if (id === '') continue
      const selected = Array.isArray(item.selected)
        ? item.selected
          .filter((label) => typeof label === 'string' && label !== '')
          .slice(0, TODO_LIMITS.options)
          .map((label) => label.slice(0, 500))
        : []
      const answer = { id, selected }
      const custom = boundText(item.custom, 4000)
      if (custom !== '') answer.custom = custom
      answers.push(answer)
    }
    return answers
  }

  /** 历史条目只保留有界文本；损坏/未知结构一律丢弃。 */
  function sanitizeHistoryEntry(raw) {
    if (raw === null || typeof raw !== 'object') return null
    const id = typeof raw.id === 'string' && raw.id !== '' ? raw.id : ''
    const outcome = HISTORY_OUTCOMES.has(raw.outcome) ? raw.outcome : ''
    const seq = Number(raw.seq)
    if (id === '' || outcome === '' || !Number.isSafeInteger(seq) || seq < 1) return null
    // 结构化问答：问题重新收敛，答案重新用问题定义校验；任一不可信就退化为 null。
    // 被拒绝的条目保存的是「拒绝那一刻的草稿」，可能没答完，用宽松校验。
    const questions = historyQuestions(raw.questions)
    let answers = null
    if (questions !== null) {
      const checked = outcome === 'rejected'
        ? validateDraftAnswers(questions, raw.answers)
        : validateAnswers(questions, raw.answers)
      if (checked.ok === true) answers = checked.answers
    }
    return {
      seq,
      id: id.slice(0, 200),
      kind: TODO_KINDS.has(raw.kind) ? raw.kind : 'approval',
      outcome,
      toolName: typeof raw.toolName === 'string' && raw.toolName !== '' ? raw.toolName.slice(0, 160) : null,
      sessionId: typeof raw.sessionId === 'string' ? raw.sessionId.slice(0, 200) : '',
      title: boundText(raw.title, TODO_LIMITS.titleChars) || '待办',
      reviewOnly: raw.reviewOnly === true,
      rejectReason: REJECTION_REASONS.has(raw.rejectReason) ? raw.rejectReason : 'offline',
      createdAt: Number.isSafeInteger(raw.createdAt) ? raw.createdAt : 0,
      decidedAt: Number.isSafeInteger(raw.decidedAt) ? raw.decidedAt : null,
      executedAt: Number.isSafeInteger(raw.executedAt) ? raw.executedAt : null,
      archivedAt: Number.isSafeInteger(raw.archivedAt) ? raw.archivedAt : 0,
      argsPreview: typeof raw.argsPreview === 'string' ? raw.argsPreview.slice(0, TODO_LIMITS.previewChars) : null,
      referencedFiles: Array.isArray(raw.referencedFiles)
        ? raw.referencedFiles.filter((item) => typeof item === 'string').slice(0, 8).map((item) => item.slice(0, 500))
        : [],
      resultSummary: typeof raw.resultSummary === 'string' ? raw.resultSummary.slice(0, TODO_LIMITS.outputPreviewChars) : null,
      failReason: typeof raw.failReason === 'string' ? raw.failReason.slice(0, TODO_LIMITS.failReasonChars) : null,
      questionCount: Number.isSafeInteger(raw.questionCount) ? raw.questionCount : 0,
      answersPreview: typeof raw.answersPreview === 'string'
        ? raw.answersPreview.slice(0, TODO_LIMITS.historyAnswersChars)
        : null,
      questions,
      answers,
    }
  }

  function loadHistory() {
    try {
      if (!existsSync(historyFile)) return
      const parsed = JSON.parse(readFileSync(historyFile, 'utf8'))
      if (parsed === null || typeof parsed !== 'object' || parsed.version !== TODO_HISTORY_VERSION) {
        log('ignoring malformed or unsupported history file:', historyFile)
        return
      }
      const raw = Array.isArray(parsed.entries) ? parsed.entries : []
      const repaired = []
      for (const item of raw) {
        const entry = sanitizeHistoryEntry(item)
        if (entry !== null) repaired.push(entry)
      }
      history = repaired.sort((left, right) => left.seq - right.seq)
      const storedSeq = Number(parsed.seq)
      const lastSeq = history.length > 0 ? history[history.length - 1].seq : 0
      historySeq = Number.isSafeInteger(storedSeq) && storedSeq >= 0 ? Math.max(storedSeq, lastSeq) : lastSeq
      log('loaded ' + history.length + ' history entr' + (history.length === 1 ? 'y' : 'ies') +
        ' from ' + historyFile)
    } catch (error) {
      log('could not load history (ignored):', messageOf(error))
    }
  }

  /**
   * 把一条活动待办归档进历史（只读浏览，不提供恢复/重放）。
   * outcome：executed | rejected | failed | restarted | answered
   */
  function archiveTodo(todo, outcome) {
    if (todo === null || typeof todo !== 'object') return null
    if (!HISTORY_OUTCOMES.has(outcome)) return null
    // 宿主热重载时新旧两个实例可能各自归档同一条待办：只保留第一次。
    if (history.some((entry) => entry.id === todo.id)) return null
    historySeq += 1
    const answers = Array.isArray(todo.answers) ? todo.answers : null
    const entry = {
      seq: historySeq,
      id: todo.id,
      kind: todo.kind,
      outcome,
      toolName: todo.toolName ?? null,
      sessionId: todo.sessionId,
      title: todo.title,
      reviewOnly: todo.reviewOnly === true,
      rejectReason: todo.rejectReason,
      createdAt: todo.createdAt ?? null,
      decidedAt: todo.decidedAt ?? null,
      executedAt: todo.executedAt ?? null,
      archivedAt: Date.now(),
      argsPreview: todo.argsPreview ?? null,
      referencedFiles: Array.isArray(todo.referencedFiles) ? todo.referencedFiles : [],
      resultSummary: todo.resultSummary ?? null,
      failReason: todo.failReason ?? null,
      questionCount: Array.isArray(todo.questions) ? todo.questions.length : 0,
      answersPreview: answers === null ? null : boundText(JSON.stringify(answers), TODO_LIMITS.historyAnswersChars),
      // 结构化快照：历史里能直接看到当时的问题选项与用户答案（旧字段保留兼容）。
      questions: historyQuestions(todo.questions),
      answers: historyAnswers(todo.answers),
    }
    history.push(entry)
    persistHistory()
    return entry
  }

  function load() {
    try {
      if (!existsSync(stateFile)) return
      const parsed = JSON.parse(readFileSync(stateFile, 'utf8'))
      if (parsed === null || typeof parsed !== 'object' || parsed.version !== TODO_STATE_VERSION) {
        log('ignoring malformed or unsupported state file:', stateFile)
        return
      }
      const raw = Array.isArray(parsed.todos) ? parsed.todos : []
      const repaired = []
      for (const item of raw) {
        const todo = sanitizeStoredTodo(item)
        if (todo === null) continue
        if (item !== null && typeof item === 'object' && item.status === 'restarting') {
          // 重启类工具执行前落盘的标记：宿主确实重启过，按“已执行（结果未知）”归档。
          todo.status = 'approved'
          if (todo.executedAt === null) todo.executedAt = Date.now()
          if (todo.resultSummary === null) {
            todo.resultSummary = '宿主已重启；该工具没有返回结果，实际效果需人工确认。'
          }
          archiveTodo(todo, 'restarted')
          log('archived restarting todo ' + todo.id + ' as restarted')
          continue
        }
        if (item !== null && typeof item === 'object' && item.status === 'executing' && item.reloadExpected === true) {
          // 安装/卸载插件会热重载正在执行 todo_execute 的 Host：待办已被受理，
          // 结果未知但不应报 failed。按已执行归档，让用户去历史里人工确认。
          todo.status = 'approved'
          todo.executedAt = Date.now()
          todo.resultSummary = '宿主在执行过程中热重载（安装/卸载插件）；待办按已执行归档，实际结果需人工确认。'
          archiveTodo(todo, 'executed')
          log('archived reload-expected executing todo ' + todo.id + ' as executed')
          continue
        }
        if (item !== null && typeof item === 'object' && item.status === 'executing') {
          todo.failReason = '宿主在执行过程中重启，原工具调用的结果未知；请人工检查后再决定重试或拒绝。'
        }
        repaired.push(todo)
      }
      if (repaired.length > cfg.maxTodos) {
        log('state file exceeds maxTodos; keeping the newest ' + cfg.maxTodos)
      }
      todos = repaired.slice(-cfg.maxTodos)
      forkedSessions = sanitizeForkedSessions(parsed.forkedSessions)
      log('loaded ' + todos.length + ' todo(s) from ' + stateFile)
    } catch (error) {
      log('could not load state (ignored):', messageOf(error))
    }
  }

  /** 持久化的「已复制分支」列表：只保留有界非空 id，去重并保留最近的若干条。 */
  function sanitizeForkedSessions(raw) {
    if (!Array.isArray(raw)) return []
    const ids = []
    for (const item of raw) {
      if (typeof item !== 'string' || item === '') continue
      const id = item.slice(0, 200)
      if (ids.includes(id)) continue
      ids.push(id)
    }
    return ids.slice(-TODO_LIMITS.forkedSessions)
  }

  loadHistory()
  load()

  function findTodo(id) {
    return todos.find((todo) => todo.id === id)
  }

  function removeTodo(id, outcome) {
    const index = todos.findIndex((todo) => todo.id === id)
    if (index === -1) return false
    const [removed] = todos.splice(index, 1)
    if (typeof outcome === 'string') archiveTodo(removed, outcome)
    persist()
    return true
  }

  /**
   * 归档删除所有 `status === 'rejected'` 的待办（outcome='rejected'）。
   *
   * 调用时机只有两处（见 README / TECHDOC）：
   *   1. `POST /api/todo-inbox/apply` 处理过程中；
   *   2. `todo_list` / `todo_get` / `todo_execute` 进入实现后、执行原逻辑前。
   * `state` / `history` / `decide` / `restore` 一律不调用，避免用户还在「已操作」
   * 分段里查看时条目被后台轮询清掉。
   *
   * 并发与幂等：整段是同步代码（Node 单线程），不会在拼接/归档中间被其它请求插入；
   * `archiveTodo()` 按 id 去重，重复调用只会归档第一次；循环里重新按 id + 状态定位，
   * 即使同一条待办已被其它路径移除也安全跳过。
   * @returns 本次归档删除的条数
   */
  function purgeRejectedTodos() {
    const ids = todos.filter((todo) => todo.status === 'rejected').map((todo) => todo.id)
    if (ids.length === 0) return 0
    let removed = 0
    for (const id of ids) {
      const index = todos.findIndex((todo) => todo.id === id && todo.status === 'rejected')
      if (index === -1) continue
      const [todo] = todos.splice(index, 1)
      archiveTodo(todo, 'rejected')
      removed += 1
    }
    if (removed > 0) {
      persist()
      log('archived ' + removed + ' rejected todo(s)')
    }
    return removed
  }

  function totals() {
    return {
      pending: todos.filter((todo) => todo.status === 'pending').length,
      approved: todos.filter((todo) => todo.status === 'approved').length,
      failed: todos.filter((todo) => todo.status === 'failed').length,
    }
  }

  // ---------------------------------------------------------------------------
  // 一次性 approval grant（供注意力门控同步消费）
  // ---------------------------------------------------------------------------
  const grants = new Map()

  function sweepGrants(now = Date.now()) {
    for (const [callId, grant] of grants) {
      if (grant.expiresAt <= now) grants.delete(callId)
    }
    if (grants.size > 100) {
      const ids = [...grants.keys()].slice(0, grants.size - 100)
      for (const id of ids) grants.delete(id)
    }
  }

  function registerGrant(callId, todoId, sessionId) {
    sweepGrants()
    grants.set(callId, { todoId, sessionId, at: Date.now(), expiresAt: Date.now() + TODO_GRANT_TTL_MS })
  }

  function removeGrant(callId) {
    grants.delete(callId)
  }

  function takeApprovalGrant(callId) {
    if (typeof callId !== 'string' || callId === '') return false
    const grant = grants.get(callId)
    if (grant === undefined) return false
    grants.delete(callId)
    if (grant.expiresAt <= Date.now()) return false
    log('approval grant consumed for todo ' + grant.todoId)
    return true
  }

  // ---------------------------------------------------------------------------
  // 危险操作：释放并删除待办缓存（设置页的红色 5 秒长按框）
  // ---------------------------------------------------------------------------

  /**
   * 一次性释放并删除本插件的待办缓存：
   *   - 删除所有 `pending` / `approved` / `rejected` / `failed`（以及任何其它非执行中状态）的待办；
   *   - **保留** `executing` / `restarting`：正在执行原工具的待办不能打断，执行结束后仍按原路径
   *     `removeTodo` / `archiveTodo` 收尾，所以保留项不会变成孤儿；
   *   - 清空历史数组、`forkedSessions` 与一次性 approval grants；
   *   - 立即 persist：写回空的 `state.json` / `history.json`，**保留文件本身**，不删除文件。
   *
   * 整段是同步代码（Node 单线程），不会与其它请求或正在执行的待办交错；`historySeq`
   * 计数器不回退，保证清空后新归档的条目 seq 仍单调递增。
   * @returns {{ todos: number, history: number, kept: number }} 各类删除/保留条数
   */
  function purgeTodoCache() {
    const kept = []
    let removedTodos = 0
    for (const todo of todos) {
      if (PURGE_KEEP_STATUSES.has(todo.status)) kept.push(todo)
      else removedTodos += 1
    }
    const removedHistory = history.length
    todos = kept
    history = []
    forkedSessions = []
    grants.clear()
    persist()
    persistHistory()
    log('purged todo cache: removed ' + removedTodos + ' todo(s), ' + removedHistory +
      ' history entr' + (removedHistory === 1 ? 'y' : 'ies') + ', kept ' + kept.length + ' executing')
    return { todos: removedTodos, history: removedHistory, kept: kept.length }
  }

  // ---------------------------------------------------------------------------
  // 自动入队：订阅 userAttention 的最终拒绝事件
  // ---------------------------------------------------------------------------
  function liveSessionById(sessionId) {
    try {
      for (const session of ctx.sessions.list()) {
        if (session !== null && session !== undefined && String(session.id) === sessionId) return session
      }
    } catch (error) {
      log('cannot list sessions:', messageOf(error))
    }
    return undefined
  }

  function readCallFromSession(sessionId, callId) {
    if (callId === null) return null
    const session = liveSessionById(sessionId)
    if (session === undefined || typeof session.ownEvents !== 'function') return null
    try {
      return findToolCallArguments(session.ownEvents(), callId)
    } catch (error) {
      log('cannot read session events for ' + sessionId + ':', messageOf(error))
      return null
    }
  }

  /**
   * 一条待办应该在哪个会话的日志里找原始 `tool/call`：
   * 分支复制来的待办指向原会话（`originSessionId`），本会话产生的仍查自己。
   */
  function callSourceSessionId(todo) {
    if (todo === null || typeof todo !== 'object') return ''
    if (typeof todo.originSessionId === 'string' && todo.originSessionId !== '') return todo.originSessionId
    return typeof todo.sessionId === 'string' ? todo.sessionId : ''
  }

  // ---------------------------------------------------------------------------
  // 分支对话复制待办
  //
  // DSH 从既有会话派生分支时发 `session/created`，分支 header 带 `parentSession`
  // （原会话 id）与 `isSeeded: true`。这里把原会话里“还没执行、也没被拒绝”的待办
  // 复制一份到分支：新 id、`sessionId` 换成分支、`originSessionId` 指回原会话；
  // 原会话的待办不受影响。执行时 `todo_execute` 用 `originSessionId` 回原会话日志
  // 取原始调用（分支的 `ownEvents()` 只返回 fork 之后的自有事件）。
  // ---------------------------------------------------------------------------
  function newTodoId() {
    let id = 'todo-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)
    while (todos.some((todo) => todo.id === id)) {
      id = 'todo-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)
    }
    return id
  }

  /** 深拷贝问题/答案这类嵌套结构：复制出来的待办不能与来源共享可变数组。 */
  function cloneTodoValue(value) {
    if (value === null || value === undefined) return null
    try {
      return JSON.parse(JSON.stringify(value))
    } catch (error) {
      return null
    }
  }

  /** 复制一条待办：新 id、新 `sessionId`、`originSessionId` 指回原会话，其余字段原样保留。 */
  function cloneTodoForFork(todo, branchSessionId, parentSessionId) {
    return {
      ...todo,
      id: newTodoId(),
      sessionId: branchSessionId,
      originSessionId: parentSessionId,
      questions: cloneTodoValue(todo.questions),
      answers: cloneTodoValue(todo.answers),
      referencedFiles: Array.isArray(todo.referencedFiles) ? todo.referencedFiles.slice(0, 8) : [],
    }
  }

  /** 记录“这个分支的复制已经处理过”，有界并随 state.json 持久化。 */
  function markForkHandled(branchSessionId) {
    if (forkedSessions.includes(branchSessionId)) return
    forkedSessions.push(branchSessionId)
    if (forkedSessions.length > TODO_LIMITS.forkedSessions) {
      forkedSessions = forkedSessions.slice(-TODO_LIMITS.forkedSessions)
    }
  }

  /**
   * 把父会话里可复制的待办复制到刚创建的分支会话。
   *
   * 只复制 `pending` / `approved`；`failed` / `executing` / `restarting` / `rejected`
   * 不复制。幂等有两条：同一分支只处理一次（`forkedSessions`，持久化），以及分支里
   * 已经有任何待办时视为已经处理过（不再复制）。
   *
   * @returns 实际复制的条数；普通会话、非 fork、已处理过都返回 0
   */
  function copyTodosToFork(session) {
    if (session === null || typeof session !== 'object') return 0
    const branchSessionId = typeof session.id === 'string' ? session.id : ''
    if (branchSessionId === '') return 0
    const header = session.header !== null && typeof session.header === 'object' ? session.header : null
    if (header === null || header.isSeeded !== true) return 0
    const parentSessionId = typeof header.parentSession === 'string' ? header.parentSession : ''
    if (parentSessionId === '' || parentSessionId === branchSessionId) return 0
    // 幂等 1：这个分支的复制已经处理过（同一次会话创建里重复事件，或恢复分支会话）。
    if (forkedSessions.includes(branchSessionId)) return 0
    // 幂等 2：分支里已经有任何待办 —— 复制过，或用户已经在该分支里操作过，不再复制。
    if (todos.some((todo) => todo.sessionId === branchSessionId)) {
      markForkHandled(branchSessionId)
      persist()
      log('fork session ' + branchSessionId.slice(0, 8) + ' already has todos; skipping copy')
      return 0
    }
    const source = todos.filter((todo) =>
      todo.sessionId === parentSessionId && FORK_COPY_STATUSES.has(todo.status))
    if (source.length === 0) {
      // 分支创建这一刻没有可复制的待办：标记为已处理，之后原会话再入队的待办不追发。
      markForkHandled(branchSessionId)
      persist()
      return 0
    }
    const room = Math.max(0, cfg.maxTodos - todos.length)
    const copies = source.slice(0, room).map((todo) => cloneTodoForFork(todo, branchSessionId, parentSessionId))
    for (const copy of copies) todos.push(copy)
    markForkHandled(branchSessionId)
    persist()
    if (copies.length < source.length) {
      log('todo inbox is full (' + cfg.maxTodos + '); copied only ' + copies.length + ' of ' +
        source.length + ' todo(s) into the fork')
    }
    return copies.length
  }

  /** `session/created` 回调：复制失败只记日志，绝不把异常抛回会话创建。 */
  function onSessionCreated(session) {
    try {
      const copied = copyTodosToFork(session)
      if (copied > 0) {
        const branchSessionId = typeof session?.id === 'string' ? session.id : ''
        const parentSessionId = typeof session?.header?.parentSession === 'string' ? session.header.parentSession : ''
        log('copied ' + copied + ' todo(s) into fork session ' + branchSessionId.slice(0, 8) +
          ' from ' + parentSessionId.slice(0, 8))
      }
    } catch (error) {
      log('fork todo copy failed:', messageOf(error))
    }
  }

  /** 自动入队开关：bundle 配置页写在注意力行；独立运行时回退到本组件配置。 */
  function effectiveAutoEnqueue() {
    try {
      const attention = ctx.get('userAttention')
      if (attention !== null && attention !== undefined && typeof attention.todoAutoEnqueue === 'function') {
        return attention.todoAutoEnqueue() === true
      }
    } catch (error) { /* 注意力组件未启用时使用本组件配置 */ }
    return cfg.autoEnqueue
  }

  function enqueueRejection(event) {
    if (!effectiveAutoEnqueue()) return
    if (event === null || typeof event !== 'object') return
    // 注意力超时策略选“拒绝”时事件带 enqueue:false；待办不保留这次交互。
    if (event.enqueue === false) return
    const kind = TODO_KINDS.has(event.kind) ? event.kind : null
    if (kind === null) return
    const sessionId = typeof event.sessionId === 'string' ? event.sessionId : ''
    if (sessionId === '') {
      log('ignoring rejection without a session id')
      return
    }
    const callId = typeof event.callId === 'string' && event.callId !== '' ? event.callId : null
    if (callId !== null && todos.some((todo) =>
      todo.kind === kind && todo.sessionId === sessionId && todo.callId === callId &&
      todo.status !== 'failed')) {
      log('ignoring duplicate rejection for ' + kind + ' ' + callId)
      return
    }
    if (todos.length >= cfg.maxTodos) {
      log('todo inbox is full (' + cfg.maxTodos + '); dropping a new rejection')
      return
    }
    const call = readCallFromSession(sessionId, callId)
    const result = createTodoRecord({
      id: newTodoId(),
      event,
      call,
      now: Date.now(),
    })
    if (result.todo === undefined) {
      log('did not enqueue rejection (' + String(result.skipped) + ')')
      return
    }
    todos.push(result.todo)
    persist()
    log('enqueued ' + result.todo.id + ' kind=' + kind + ' session=' + sessionId.slice(0, 8) +
      (result.todo.reviewOnly ? ' (review-only)' : ''))
  }

  function subscribeAttention(attention) {
    if (attention === null || attention === undefined || typeof attention.onRejection !== 'function') return false
    ctx.effect(
      () => attention.onRejection((event) => {
        try {
          enqueueRejection(event)
        } catch (error) {
          log('auto-enqueue failed:', messageOf(error))
        }
      }),
      'todo-inbox: auto enqueue',
    )
    log('subscribed to userAttention rejection events')
    return true
  }

  let subscribed = false
  try {
    // 合并后 userAttention 由同一个 apply 里先注册，直接取即可；保留动态等待以兼容旧装配。
    subscribed = subscribeAttention(ctx.get('userAttention'))
  } catch (error) {
    log('direct userAttention lookup failed:', messageOf(error))
  }
  if (!subscribed) {
    try {
      ctx.inject(['userAttention'], (scope) => {
        if (!subscribeAttention(scope.get('userAttention'))) {
          log('userAttention service has no onRejection(); auto-enqueue disabled')
        }
      })
    } catch (error) {
      log('userAttention subscription failed:', messageOf(error))
    }
  }

  // ---------------------------------------------------------------------------
  // 分支对话复制待办：订阅 session/created
  // ---------------------------------------------------------------------------
  try {
    if (typeof ctx.on !== 'function') {
      log('ctx.on unavailable; fork todo copy disabled')
    } else {
      ctx.effect(() => ctx.on('session/created', onSessionCreated), 'todo-inbox: fork copy todos')
      log('subscribed to session/created for fork todo copy')
    }
  } catch (error) {
    log('fork todo copy subscription failed:', messageOf(error))
  }

  // ---------------------------------------------------------------------------
  // 语义化提醒注入（批准/拒绝/回答后通知来源会话的模型，不主动唤醒）
  // ---------------------------------------------------------------------------
  function injectNotice(sessionId, text, summary) {
    const agents = safeGet('agents')
    if (agents === undefined || typeof agents.get !== 'function') return false
    let agent
    try {
      agent = agents.get(sessionId)
    } catch (error) {
      return false
    }
    if (agent === undefined || agent === null || typeof agent.inject !== 'function') return false
    try {
      agent.inject({
        role: 'user',
        id: uuid(),
        content: [{ type: 'text', text }],
        source: { kind: 'todo-inbox', form: 'notice', summary: boundText(summary, 120) },
      })
      return true
    } catch (error) {
      log('could not inject todo notice into ' + sessionId + ':', messageOf(error))
      return false
    }
  }

  function notifyDecided(todo, action) {
    if (action === 'reject') {
      return injectNotice(
        todo.sessionId,
        '用户拒绝了待办 ' + todo.id + (todo.toolName === null ? '' : '（工具 ' + todo.toolName + '）') +
          '。这次操作不会执行；不要再次尝试该项，除非用户明确要求。',
        '待办已被用户拒绝',
      )
    }
    if (action === 'answer') {
      return injectNotice(
        todo.sessionId,
        '用户已回答待办 ' + todo.id + '。请调用 todo_execute（参数 id=' + todo.id + '）取回答案并继续。',
        '待办问题已回答',
      )
    }
    return injectNotice(
      todo.sessionId,
      '用户已操作待办 ' + todo.id + (todo.toolName === null ? '' : '（工具 ' + todo.toolName + '）') +
        '。你可以调用 todo_execute（参数 id=' + todo.id + '）执行一次；用户也可能直接点击“应用操作”发送执行请求。',
      '待办已被用户操作',
    )
  }

  // ---------------------------------------------------------------------------
  // 工具实现
  // ---------------------------------------------------------------------------
  function requireCallerAgent(exec, toolName) {
    const agent = exec.agent
    if (agent === undefined || agent === null) throw new Error(toolName + ' 需要由 AI 调用')
    let live
    try {
      live = ctx.agents.get(agent.id)
    } catch (error) {
      live = undefined
    }
    if (live !== agent) throw new Error(toolName + ' 需要当前存活的调用 AI')
    return agent
  }

  function callerSessionId(agent) {
    return String(agent.id)
  }

  function listTodosForSession(sessionId, limit) {
    return todos
      .filter((todo) => todo.sessionId === sessionId)
      .slice(-Math.min(limit, TODO_LIMITS.toolListLimit))
      .map(summarizeTodo)
      .filter(Boolean)
  }

  /**
   * 模型可见的待办列表：除了状态，还要给出“目的 + 工具 + 参数预览”，
   * 这样模型才能自己判断执行顺序（例如先跑逃生舱命令、再上保险、最后强重启）。
   */
  function renderTodosText(payload, sessionId) {
    const items = Array.isArray(payload.items) ? payload.items : []
    if (items.length === 0) return '当前会话没有待办（todo-inbox v' + PLUGIN_VERSION + '）。'
    const lines = ['（下面是复核信息：目的 + 脱敏参数预览。完整参数用 todo_get；批量执行用 ids + mode，顺序由你决定。）',
      '待办收件箱（todo-inbox v' + PLUGIN_VERSION + '，会话 ' + sessionId.slice(0, 8) + '）：共 ' + payload.total + ' 项，' +
      '待审核 ' + payload.pending + '，已操作 ' + payload.approved + '，失败 ' + payload.failed + '。']
    for (const item of items) {
      const flags = [item.status, item.kind]
      if (item.reviewOnly) flags.push('仅复核')
      lines.push('- ' + item.id + ' [' + flags.join(' / ') + '] ' + item.title)
      if (typeof item.toolName === 'string' && item.toolName !== '') lines.push('  工具：' + item.toolName)
      if (typeof item.originSessionId === 'string' && item.originSessionId !== '' &&
        item.originSessionId !== sessionId) {
        lines.push('  来源：分支复制（原会话 ' + item.originSessionId.slice(0, 8) + '；执行时回原会话日志取参数）')
      }
      if (typeof item.requestReason === 'string' && item.requestReason !== '') {
        lines.push('  目的：' + boundText(item.requestReason, 240))
      }
      if (typeof item.argsPreview === 'string' && item.argsPreview !== '') {
        lines.push('  参数预览：' + boundText(item.argsPreview, 300))
      } else if (typeof item.detail === 'string' && item.detail !== '') {
        lines.push('  说明：' + boundText(item.detail, 240))
      }
    }
    if (payload.total > items.length) lines.push('（只显示最近 ' + items.length + ' 项）')
    return lines.join('\n')
  }

  const todoListTool = {
    name: 'todo_list',
    description:
      '列出来源为当前会话的待办收件箱条目（只读）。每条给出：id、状态、类型、工具名、标题、目的（原始审批理由）、' +
      '脱敏参数预览（命令行/调用参数）与创建时间，便于你自行判断执行顺序；完整参数用 todo_get。' +
      '待办由用户注意力插件在用户暂离/离线导致批准或提问被自动拒绝时生成；用户批准或回答后才能用 todo_execute 执行。' +
      '用分支对话派生的会话会复制原会话里未执行、未拒绝的待办（带 originSessionId），列表里会注明来源。' +
      '默认最多 30 条。',
    parameters: {
      type: 'object',
      properties: {
        limit: { type: 'integer', description: '最多返回多少条（默认 30，上限 30）。' },
      },
      additionalProperties: false,
    },
    output: {
      schema: {
        type: 'object',
        properties: {
          sessionId: { type: 'string' },
          total: { type: 'number' },
          pending: { type: 'number' },
          approved: { type: 'number' },
          failed: { type: 'number' },
          items: { type: 'array', items: { type: 'object', additionalProperties: true } },
          message: { type: 'string' },
        },
        additionalProperties: true,
      },
      render: (_args, value) => [{ type: 'text', text: typeof value?.message === 'string' ? value.message : JSON.stringify(value) }],
    },
    presentCall: () => ({ card: 'generic', title: '查看待办收件箱', kind: 'read' }),
    async execute(args, exec) {
      // 删除时机：AI 调用任一 todo_* 工具时，先把 rejected 条目归档删除再执行原逻辑。
      purgeRejectedTodos()
      const agent = requireCallerAgent(exec, 'todo_list')
      const sessionId = callerSessionId(agent)
      const limit = typeof args?.limit === 'number' && Number.isSafeInteger(args.limit)
        ? Math.min(Math.max(args.limit, 1), TODO_LIMITS.toolListLimit)
        : TODO_LIMITS.toolListLimit
      const sessionTodos = todos.filter((todo) => todo.sessionId === sessionId)
      const payload = {
        sessionId,
        total: sessionTodos.length,
        ...totalsForScoped(sessionTodos),
        items: listTodosForSession(sessionId, limit),
      }
      return { ...payload, message: renderTodosText(payload, sessionId) }
    },
  }

  function totalsForScoped(items) {
    return {
      pending: items.filter((todo) => todo.status === 'pending').length,
      approved: items.filter((todo) => todo.status === 'approved').length,
      failed: items.filter((todo) => todo.status === 'failed').length,
    }
  }

  const todoGetTool = {
    name: 'todo_get',
    description:
      '读取当前会话某条待办的完整复核信息（只读）：问题/选项、脱敏参数预览、拒绝原因、状态。不返回用户答案；' +
      '答案只能通过 todo_execute 在用户回答后取回。跨会话的 id 一律拒绝。' +
      '分支复制来的待办会注明来源（originSessionId 指向原会话）。',
    parameters: {
      type: 'object',
      properties: { id: { type: 'string', description: '待办 id，例如 todo-xxxx。' } },
      required: ['id'],
      additionalProperties: false,
    },
    output: {
      schema: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          todo: { type: 'object', additionalProperties: true },
          message: { type: 'string' },
        },
        additionalProperties: true,
      },
      render: (_args, value) => [{ type: 'text', text: typeof value?.message === 'string' ? value.message : JSON.stringify(value) }],
    },
    presentCall: () => ({ card: 'generic', title: '查看待办详情', kind: 'read' }),
    async execute(args, exec) {
      // 删除时机：AI 调用任一 todo_* 工具时，先把 rejected 条目归档删除再执行原逻辑。
      purgeRejectedTodos()
      const agent = requireCallerAgent(exec, 'todo_get')
      const sessionId = callerSessionId(agent)
      const id = typeof args?.id === 'string' ? args.id.trim() : ''
      if (id === '') throw new Error('todo_get 需要 id 参数')
      const todo = findTodo(id)
      if (todo === undefined) throw new Error('待办不存在或已被处理：' + id)
      if (todo.sessionId !== sessionId) throw new Error('这条待办属于其他会话，只能在来源会话中查看和执行')
      const detail = detailTodo(todo)
      const lines = [
        '待办 ' + todo.id + '：' + todo.title,
        '状态：' + todo.status + '；类型：' + todo.kind + '；拒绝原因：' + (REASON_LABELS[todo.rejectReason] ?? todo.rejectReason),
      ]
      if (todo.toolName !== null) lines.push('工具：' + todo.toolName)
      if (todo.requestReason !== null) lines.push('目的：' + todo.requestReason)
      if (todo.reviewOnly) lines.push('标记：仅复核（不可执行）')
      if (typeof todo.originSessionId === 'string' && todo.originSessionId !== '' &&
        todo.originSessionId !== todo.sessionId) {
        lines.push('来源：由分支对话复制自原会话 ' + todo.originSessionId.slice(0, 8) +
          '（原始调用在原会话日志里；执行时按 originSessionId 取回参数）')
      }
      if (todo.questions !== null && todo.questions.length > 0) {
        for (const question of todo.questions) {
          lines.push('问题 ' + question.id + '：' + question.question)
          if (Array.isArray(question.options)) {
            lines.push('  选项：' + question.options.map((option) => option.label).join(' / '))
          }
        }
      }
      if (todo.argsPreview !== null) lines.push('参数预览：' + todo.argsPreview)
      if (todo.failReason !== null) lines.push('上次失败：' + todo.failReason)
      return { id, todo: detail, message: lines.join('\n') }
    },
  }

  /** DSH 官方 Agent 循环里的“并行工具调用数”；读不到时回退 10（官方默认）。 */
  function officialParallelLimit() {
    try {
      const loop = safeGet('agentLoop')
      const holder = loop !== null && typeof loop === 'object' ? loop.config : undefined
      const raw = holder !== null && typeof holder === 'object' ? holder.maxParallelToolCalls : undefined
      const value = raw !== null && typeof raw === 'object' && typeof raw.get === 'function' ? raw.get() : raw
      const n = Number(value)
      if (Number.isSafeInteger(n) && n >= 1) return n
    } catch (error) { /* 设置不可读时使用默认值 */ }
    return 10
  }

  /** 执行后会重启宿主的工具（status 只读、force_safeguard 只上保险，都不算）。 */
  function isRestartTool(toolName) {
    return typeof toolName === 'string' && RESTART_TOOL_PATTERN.test(toolName)
  }

  function prepareTodoForExecution(id, sessionId) {
    const todo = findTodo(id)
    if (todo === undefined) throw new Error('待办不存在或已被处理：' + id)
    if (todo.sessionId !== sessionId) throw new Error('这条待办属于其他会话，只能由来源会话的 AI 执行：' + id)
    if (todo.status === 'executing' || todo.status === 'restarting') {
      throw new Error('待办 ' + id + ' 正在执行中，请勿重复调用')
    }
    if (todo.status === 'rejected') {
      // 正常路径下 todo_execute 入口已把 rejected 归档删除；这里兜住直连服务的旧调用。
      throw new Error('待办 ' + id + ' 已被用户拒绝；请让用户先点“返回修改”再执行')
    }
    if (todo.status === 'pending') {
      throw new Error('待办 ' + id + ' 还没有被用户批准/回答；请让用户在待办收件箱里处理后再执行')
    }
    if (todo.kind === 'question') {
      if (!Array.isArray(todo.answers) || todo.answers.length === 0) {
        throw new Error('用户还没有回答这条待办的问题：' + id)
      }
      return todo
    }
    if (todo.reviewOnly) throw new Error('待办 ' + id + ' 标记为仅复核（元工具不可有意义重放）；只能拒绝或删除')
    if (todo.callId === null) throw new Error('待办 ' + id + ' 缺少原始 callId，无法从会话日志取回参数')
    if (todo.toolName === null) throw new Error('待办 ' + id + ' 缺少工具名，无法执行')
    return todo
  }

  function takeQuestionAnswers(todo) {
    const answers = Array.isArray(todo.answers) ? todo.answers : []
    const payload = answers.map((answer) => ({ ...answer }))
    removeTodo(todo.id, 'answered')
    return {
      id: todo.id,
      ok: true,
      kind: 'question',
      toolName: '',
      executed: false,
      answers: payload,
      outputPreview: '',
      message: '用户对待办 ' + todo.id + ' 的回答已取回（待办已删除）。',
    }
  }

  /**
   * 执行单条 approval 待办。成功返回结果对象；失败抛错（由批量调度决定是否继续）。
   * 重启类工具在调用前把状态落成 restarting：宿主重启后由 load() 归档，不会误报 failed。
   */
  async function executeApprovalTodo(todo, agent, signal) {
    // 分支复制来的待办：原始 tool/call 在父会话日志里（分支 ownEvents() 只有自有事件），
    // 所以优先按 originSessionId 查；普通待办回退到 sessionId。
    const call = readCallFromSession(callSourceSessionId(todo), todo.callId)
    if (call === null) {
      throw new Error('无法从来源会话日志定位原始工具调用（会话可能已归档或日志已清理）；待办保留，可检查后重试')
    }
    if (call.name !== '' && call.name !== todo.toolName) throw new Error('会话日志中的工具名与待办不一致，拒绝执行')
    if (todo.argsHash !== null && sha256Hex(call.arguments) !== todo.argsHash) {
      throw new Error('原始参数哈希校验失败，拒绝执行')
    }
    let parsedArgs
    try {
      parsedArgs = call.arguments === '' ? {} : JSON.parse(call.arguments)
    } catch (error) {
      throw new Error('会话日志中的原始参数不是合法 JSON，拒绝执行')
    }

    const restarting = isRestartTool(todo.toolName)
    const callId = ('todo-exec-' + todo.id + '-' + Date.now().toString(36)).slice(0, 200)
    // 安装/卸载插件会热重载正在执行 todo_execute 的 Host：把“已受理、结果未知”落盘，
    // 让重载后的 load() 归入历史（executed）而不是误报 failed。
    // 在状态写入前后各置一次，确保紧跟着 executing 的那份持久化快照一定带着标记。
    todo.reloadExpected = todo.toolName === 'plugin_manager'
    todo.status = restarting ? 'restarting' : 'executing'
    todo.reloadExpected = todo.toolName === 'plugin_manager'
    todo.executedAt = null
    persist()
    registerGrant(callId, todo.id, todo.sessionId)
    try {
      const result = await ctx.tools.execute({
        callId,
        name: todo.toolName,
        arguments: parsedArgs,
        agent,
        signal,
      })
      if (result.isError === true) {
        const preview = flattenContent(result.content, TODO_LIMITS.failReasonChars)
        todo.status = 'failed'
        todo.failReason = preview === '' ? '原工具执行失败（无错误文本）' : preview
        todo.executedAt = null
        persist()
        throw new Error('原工具执行失败：' + (todo.failReason ?? '未知错误') + '（待办保留为 failed，可检查后重试）')
      }
      // plugin_manager 这类工具会把业务失败放在成功结果值里；不能当成功删待办。
      const valueFailure = detectToolValueFailure(result.value)
      if (valueFailure !== null) {
        const preview = flattenContent(result.content, TODO_LIMITS.failReasonChars)
        todo.status = 'failed'
        todo.failReason = boundText('原工具报告失败：' + valueFailure + (preview === '' ? '' : '；' + preview), TODO_LIMITS.failReasonChars)
        todo.executedAt = null
        persist()
        throw new Error('原工具报告失败：' + (todo.failReason ?? valueFailure) + '（待办保留为 failed，可检查后重试）')
      }
      // pwsh/bash 的非零退出码是 isError === false 的“正常结果”，同样要保留 failed。
      const processFailure = detectProcessFailure(result.value, flattenContent(result.content, TODO_LIMITS.failReasonChars * 4))
      if (processFailure !== null) {
        const preview = flattenContent(result.content, TODO_LIMITS.failReasonChars)
        todo.status = 'failed'
        todo.failReason = boundText('命令执行失败：' + processFailure + (preview === '' ? '' : '；' + preview), TODO_LIMITS.failReasonChars)
        todo.executedAt = null
        persist()
        throw new Error('命令执行失败：' + (todo.failReason ?? processFailure) + '（待办保留为 failed，可检查后重试）')
      }
      const outputPreview = flattenContent(result.content)
      todo.status = 'approved'
      todo.executedAt = Date.now()
      todo.resultSummary = outputPreview
      removeTodo(todo.id, 'executed')
      log('executed todo ' + todo.id + ' tool=' + todo.toolName + ' callId=' + callId)
      return {
        id: todo.id,
        ok: true,
        kind: 'approval',
        toolName: todo.toolName,
        executed: true,
        outputPreview,
        message: '已执行待办 ' + todo.id + ' 对应的 ' + todo.toolName + '（一次）；待办已删除。' +
          (outputPreview === '' ? '工具没有返回文本输出。' : ''),
      }
    } catch (error) {
      // 重启类工具返回了，说明宿主没有重启（或被工具拒绝）：仍按失败保留记录。
      if (todo.status === 'executing' || todo.status === 'restarting') {
        todo.status = 'failed'
        todo.failReason = boundText(messageOf(error), TODO_LIMITS.failReasonChars) || '执行失败'
        persist()
        log('todo execution failed for ' + todo.id + ': ' + todo.failReason)
      }
      throw error
    } finally {
      removeGrant(callId)
    }
  }

  function skippedResult(todo) {
    return {
      id: todo.id,
      ok: false,
      kind: todo.kind,
      toolName: todo.toolName,
      executed: false,
      skipped: true,
      error: '前一条执行失败或触发重启，已跳过',
    }
  }

  /**
   * 批量执行：serial 默认串行，首个失败后停止（continueOnError=true 可继续）；
   * parallel 用 DSH 官方 Agent 循环的并行工具调用数作为并发上限。
   */
  async function runTodoBatch(prepared, agent, signal, mode, continueOnError) {
    const items = new Array(prepared.length)
    if (mode === 'parallel') {
      let next = 0
      const limit = Math.max(1, Math.min(officialParallelLimit(), prepared.length))
      const worker = async () => {
        for (;;) {
          const index = next
          next += 1
          if (index >= prepared.length) return
          const todo = prepared[index]
          try {
            items[index] = todo.kind === 'question'
              ? takeQuestionAnswers(todo)
              : await executeApprovalTodo(todo, agent, signal)
          } catch (error) {
            items[index] = {
              id: todo.id,
              ok: false,
              kind: todo.kind,
              toolName: todo.toolName,
              executed: false,
              error: boundText(messageOf(error), TODO_LIMITS.failReasonChars) || '执行失败',
            }
          }
        }
      }
      await Promise.all(Array.from({ length: limit }, () => worker()))
    } else {
      let stopped = false
      for (let index = 0; index < prepared.length; index += 1) {
        const todo = prepared[index]
        if (stopped) {
          items[index] = skippedResult(todo)
          continue
        }
        try {
          items[index] = todo.kind === 'question'
            ? takeQuestionAnswers(todo)
            : await executeApprovalTodo(todo, agent, signal)
        } catch (error) {
          items[index] = {
            id: todo.id,
            ok: false,
            kind: todo.kind,
            toolName: todo.toolName,
            executed: false,
            error: boundText(messageOf(error), TODO_LIMITS.failReasonChars) || '执行失败',
          }
          if (!continueOnError) stopped = true
        }
        // 重启类工具执行后宿主本来就会重启；若它返回了（失败），同样不该继续后面的条目。
        if (todo.kind === 'approval' && isRestartTool(todo.toolName)) stopped = true
      }
    }
    return items
  }

  function summarizeBatch(items, mode) {
    const succeeded = items.filter((item) => item !== undefined && item.ok === true).length
    const failed = items.filter((item) => item !== undefined && item.ok === false && item.skipped !== true).length
    const skipped = items.filter((item) => item !== undefined && item.skipped === true).length
    const lines = ['批量执行 ' + items.length + ' 条（' + (mode === 'parallel' ? '并行' : '串行') + '）：成功 ' +
      succeeded + '，失败 ' + failed + (skipped > 0 ? '，跳过 ' + skipped : '') + '。']
    for (const item of items) {
      if (item === undefined) continue
      if (item.ok === true) {
        lines.push('- ' + item.id + ' ✅ ' + (item.executed === false ? '已回答（取回答案）' : '已执行'))
      } else if (item.skipped === true) {
        lines.push('- ' + item.id + ' ⏭ 已跳过')
      } else {
        lines.push('- ' + item.id + ' ❌ ' + (item.error ?? '执行失败'))
      }
    }
    return { succeeded, failed, skipped, message: lines.join('\n') }
  }

  const todoExecuteTool = {
    name: 'todo_execute',
    description:
      '执行一条或多条已被用户操作（批准或回答）的待办；参数只接受待办 id，不接受工具参数。' +
      '单条用 id，批量用 ids（最多 10 条），mode 可选 serial（默认，按传入顺序串行）或 parallel（按 DSH Agent 循环的并行工具调用数并发）。' +
      'approval 类型会从原会话日志按 callId 取回原始参数并校验哈希，然后通过一次性授权执行原工具一次；' +
      '分支复制来的待办用 originSessionId 回原会话日志取参数（分支自己的日志里没有父会话的 tool/call）；' +
      'question 类型只返回用户保存的答案，不重放 ask_user_question。' +
      '串行默认在首个失败后停止并把后续标记 skipped，continueOnError=true 可改为继续；并行按官方并发数同时执行，' +
      '包含重启类工具时宿主可能中途重启，未返回的条目标记 restarting 并在重启后归档为已执行。' +
      '必须由待办来源会话的 AI 调用；跨会话、未批准、仅复核、日志缺失、哈希不符都会被拒绝。' +
      '执行成功或问题答案返回后待办即删除；工具执行失败时待办保留为 failed，可检查后重试。' +
      '进入本工具（以及 todo_list / todo_get）时会先把用户已拒绝（rejected）的条目归档删除。' +
      'restart_dsh_* 已允许执行：真正的重启类工具在调用前落 restarting，宿主重启后该条按“已执行（结果未知）”归档到历史。',
    parameters: {
      type: 'object',
      properties: {
        id: { type: 'string', description: '单条待办的 id，例如 todo-xxxx。' },
        ids: {
          type: 'array',
          items: { type: 'string' },
          description: '批量执行的待办 id 列表（最多 10 条，不能与 id 同时使用）。',
        },
        mode: {
          type: 'string',
          enum: ['serial', 'parallel'],
          description: '批量执行方式，默认 serial（按传入顺序串行）。parallel 使用 DSH Agent 循环的并行工具调用数。',
        },
        continueOnError: {
          type: 'boolean',
          description: '仅串行有效：首条失败后是否继续执行后续条目，默认 false。',
        },
      },
      additionalProperties: false,
    },
    output: {
      schema: {
        type: 'object',
        properties: {
          ok: { type: 'boolean' },
          mode: { type: 'string' },
          id: { type: 'string' },
          ids: { type: 'array', items: { type: 'string' } },
          kind: { type: 'string' },
          toolName: { type: 'string' },
          executed: { type: 'boolean' },
          answers: { type: 'array', items: { type: 'object', additionalProperties: true } },
          outputPreview: { type: 'string' },
          succeeded: { type: 'number' },
          failed: { type: 'number' },
          skipped: { type: 'number' },
          items: { type: 'array', items: { type: 'object', additionalProperties: true } },
          message: { type: 'string' },
        },
        additionalProperties: true,
      },
      render: (_args, value) => [{ type: 'text', text: renderTodoExecuteText(value) }],
    },
    presentCall: () => ({ card: 'generic', title: '执行待办', kind: 'execute' }),
    async execute(args, exec) {
      // 删除时机：AI 调用任一 todo_* 工具时，先把 rejected 条目归档删除再执行原逻辑。
      purgeRejectedTodos()
      const agent = requireCallerAgent(exec, 'todo_execute')
      const sessionId = callerSessionId(agent)
      const rawIds = Array.isArray(args?.ids)
        ? args.ids
        : (typeof args?.id === 'string' ? [args.id] : [])
      const ids = rawIds
        .map((value) => (typeof value === 'string' ? value.trim() : ''))
        .filter((value) => value !== '')
      if (ids.length === 0) throw new Error('todo_execute 需要 id 或 ids 参数')
      if (ids.length > TODO_LIMITS.batch) throw new Error('一次最多执行 ' + TODO_LIMITS.batch + ' 条待办')
      if (new Set(ids).size !== ids.length) throw new Error('ids 里存在重复的待办 id')
      const mode = args?.mode === 'parallel' ? 'parallel' : 'serial'
      const continueOnError = args?.continueOnError === true
      const prepared = ids.map((id) => prepareTodoForExecution(id, sessionId))
      const items = await runTodoBatch(prepared, agent, exec.signal, mode, continueOnError)
      const summary = summarizeBatch(items, mode)
      const ok = summary.failed === 0 && summary.skipped === 0
      const first = items.length === 1 ? items[0] : undefined
      const payload = {
        ok,
        mode,
        ids,
        succeeded: summary.succeeded,
        failed: summary.failed,
        skipped: summary.skipped,
        items,
        message: summary.message,
      }
      if (first !== undefined) {
        payload.id = first.id
        payload.kind = first.kind
        payload.toolName = first.toolName
        payload.executed = first.executed === true
        if (Array.isArray(first.answers)) payload.answers = first.answers
        if (typeof first.outputPreview === 'string') payload.outputPreview = first.outputPreview
        if (first.ok !== true) payload.error = first.error
      }
      return payload
    },
  }

  function registerTools() {
    ctx.effect(() => ctx.tools.register(todoListTool), 'todo-inbox: todo_list tool')
    ctx.effect(() => ctx.tools.register(todoGetTool), 'todo-inbox: todo_get tool')
    ctx.effect(() => ctx.tools.register(todoExecuteTool), 'todo-inbox: todo_execute tool')
    log('registered todo tools: todo_list, todo_get, todo_execute')
  }
  registerTools()

  // ---------------------------------------------------------------------------
  // Host service：todoInbox（注意力门控查询一次性 approval grant）
  // ---------------------------------------------------------------------------
  function provideTodoService() {
    if (typeof ctx.provide !== 'function') {
      log('ctx.provide unavailable; todoInbox service not registered')
      return
    }
    const service = {
      version: 1,
      autoEnqueueEnabled() {
        return effectiveAutoEnqueue()
      },
      list(sessionId, limit) {
        const items = typeof sessionId === 'string'
          ? todos.filter((todo) => todo.sessionId === sessionId)
          : todos.slice()
        const capped = Math.min(typeof limit === 'number' && limit > 0 ? Math.floor(limit) : TODO_LIMITS.listLimit, TODO_LIMITS.listLimit)
        return items.slice(-capped).map(summarizeTodo).filter(Boolean)
      },
      get(id) {
        const todo = findTodo(String(id))
        return todo === undefined ? null : detailTodo(todo)
      },
      takeApprovalGrant(callId) {
        return takeApprovalGrant(String(callId))
      },
      totals,
    }
    try {
      ctx.effect(() => ctx.provide('todoInbox', service), 'todo-inbox: host service')
      log('todoInbox Host service registered')
    } catch (error) {
      log('could not register the todoInbox Host service:', messageOf(error))
    }
  }
  provideTodoService()

  // ---------------------------------------------------------------------------
  // 浏览器侧 HTTP 路由（与页面同源、经应用鉴权栅栏）
  // ---------------------------------------------------------------------------
  async function readJsonBody(request) {
    try {
      const parsed = await request.json()
      return parsed !== null && typeof parsed === 'object' ? parsed : {}
    } catch (error) {
      return {}
    }
  }

  /** 定位本插件在 profile 补丁里的配置行：优先 options.name，回退 options.id。 */
  function findConfigTarget() {
    let editor
    try {
      editor = ctx.get('configEditor')
    } catch (error) {
      editor = undefined
    }
    if (editor === undefined || editor === null || typeof editor.entries !== 'function') {
      return { editor: undefined, entry: undefined }
    }
    let rows = []
    try {
      rows = editor.entries()
    } catch (error) {
      rows = []
    }
    const list = Array.isArray(rows) ? rows : []
    const usable = (row) => row !== null && typeof row === 'object' &&
      row.options !== null && typeof row.options === 'object'
    const entry = list.find((row) => usable(row) && row.options.name === '@local/dsh-todo-inbox') ||
      list.find((row) => usable(row) && row.options.id === 'todo-inbox')
    return { editor, entry }
  }

  function stateSnapshot(request) {
    let sessionFilter = null
    let scopeAll = false
    try {
      const url = new URL(request.url)
      const session = url.searchParams.get('session')
      if (typeof session === 'string' && session !== '') sessionFilter = session
      scopeAll = url.searchParams.get('scope') === 'all'
    } catch (error) { /* URL 解析失败时退回全部会话 */ }
    const view = scopeAll || sessionFilter === null
      ? todos.slice()
      : todos.filter((todo) => todo.sessionId === sessionFilter)
    // 默认作用域的信号：只针对请求里点名的会话计算，随 snapshot 一起返回，客户端只消费。
    // 没有 session 参数、或该会话不在活会话列表里（冷会话/已归档）时为 null（未知），
    // 由客户端按“已有内容”兜底，避免老服务/冷会话把所有人当新会话。
    const sessionHasContent = sessionFilter === null
      ? null
      : detectSessionHasContent(liveSessionById(sessionFilter))
    const items = view
      .slice(-TODO_LIMITS.listLimit)
      .map((todo) => {
        const summary = summarizeTodo(todo)
        if (summary === null) return null
        // Client 的待办卡片需要问题与选项；模型列表工具仍只拿摘要。
        return {
          ...summary,
          questions: todo.kind === 'question' && Array.isArray(todo.questions) ? todo.questions : null,
          // 问答类待办的「草稿答案」：拒绝时保存，供「已操作」只读展示与「返回修改」预填。
          // 模型侧投影（summarizeTodo / detailTodo）仍然不含 answers。
          answers: todo.kind === 'question' && Array.isArray(todo.answers) ? todo.answers : null,
        }
      })
      .filter(Boolean)
    let attention = null
    try { attention = ctx.get('userAttention') } catch (error) { attention = null }
    const attentionAvailable = attention !== null && attention !== undefined && typeof attention.onRejection === 'function'
    let attentionState = null
    if (attentionAvailable && typeof attention.snapshot === 'function') {
      try { attentionState = attention.snapshot().state } catch (error) { attentionState = null }
    }
    return {
      ok: true,
      version: 1,
      now: Date.now(),
      instanceId,
      attentionAvailable,
      attentionState,
      config: { autoEnqueue: effectiveAutoEnqueue(), pollIntervalMs: cfg.pollIntervalMs },
      totals: totals(),
      viewTotals: totalsForScoped(view),
      sessionId: sessionFilter,
      sessionHasContent,
      todos: items,
    }
  }

  /**
   * 只读历史快照：scope=session 必须带会话 id；scope=all 返回全部会话，每条自带 sessionId。
   * 分页用 before=seq（上一页返回的 nextBefore），最新在前；历史不参与任何执行/恢复。
   */
  function historySnapshot(request) {
    let scope = 'session'
    let sessionFilter = null
    let limit = 30
    let before = null
    try {
      const url = new URL(request.url)
      if (url.searchParams.get('scope') === 'all') scope = 'all'
      const session = url.searchParams.get('session')
      if (typeof session === 'string' && session !== '') sessionFilter = session
      const rawLimit = Number(url.searchParams.get('limit'))
      if (Number.isSafeInteger(rawLimit) && rawLimit > 0) limit = Math.min(rawLimit, 100)
      const rawBefore = Number(url.searchParams.get('before'))
      if (Number.isSafeInteger(rawBefore) && rawBefore > 0) before = rawBefore
    } catch (error) { /* URL 解析失败时使用默认值 */ }
    if (scope === 'session' && sessionFilter === null) {
      return { status: 400, body: { ok: false, error: 'scope=session 需要 session 参数' } }
    }
    const scoped = scope === 'all'
      ? history
      : history.filter((entry) => entry.sessionId === sessionFilter)
    const visible = before === null ? scoped : scoped.filter((entry) => entry.seq < before)
    const page = visible.slice(-limit).reverse()
    const nextBefore = visible.length > page.length ? page[page.length - 1].seq : null
    return {
      status: 200,
      body: {
        ok: true,
        scope,
        sessionId: sessionFilter,
        total: scoped.length,
        items: page,
        nextBefore,
      },
    }
  }

  function registerRoutes() {
    const connection = ctx.get('connection')
    if (connection === undefined || connection === null || connection.fetch === undefined ||
      typeof connection.fetch.register !== 'function') {
      log('connection.fetch unavailable; routes not registered')
      return
    }
    const routeRegister = (route, label) => {
      try {
        ctx.effect(() => connection.fetch.register(route), label)
      } catch (error) {
        log('route registration failed:', label, messageOf(error))
      }
    }

    routeRegister({
      path: '/api/todo-inbox/state',
      methods: ['GET'],
      requestBody: 'buffered',
      fetch: async (request) => {
        try {
          return jsonResponse(stateSnapshot(request))
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: state route')

    routeRegister({
      path: '/api/todo-inbox/history',
      methods: ['GET'],
      requestBody: 'buffered',
      fetch: async (request) => {
        try {
          const result = historySnapshot(request)
          return jsonResponse(result.body, result.status)
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: history route')

    routeRegister({
      path: '/api/todo-inbox/purge',
      methods: ['POST'],
      requestBody: 'buffered',
      // 危险操作：只由本机 UI（同源页面）在 5 秒长按确认后调用，无需请求体与审批。
      fetch: async () => {
        try {
          const result = purgeTodoCache()
          return jsonResponse({ ok: true, todos: result.todos, history: result.history, kept: result.kept })
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: purge route')

    routeRegister({
      path: '/api/todo-inbox/decide',
      methods: ['POST'],
      requestBody: 'buffered',
      fetch: async (request) => {
        try {
          const body = await readJsonBody(request)
          const id = typeof body.id === 'string' ? body.id.trim() : ''
          const action = typeof body.action === 'string' ? body.action : ''
          if (id === '') return jsonResponse({ ok: false, error: 'id is required' }, 400)
          if (!['approve', 'reject', 'answer', 'restore'].includes(action)) {
            return jsonResponse({ ok: false, error: 'action must be approve|reject|answer|restore' }, 400)
          }
          const todo = findTodo(id)
          if (todo === undefined) return jsonResponse({ ok: false, code: 'NOT_FOUND', error: '待办不存在或已被处理' }, 404)
          if (todo.status === 'executing' || todo.status === 'restarting') {
            return jsonResponse({ ok: false, code: 'EXECUTING', error: '待办正在执行中，不能修改' }, 409)
          }
          if (action === 'restore') {
            // 仅 rejected 可返回修改：置回 pending、清空审批时间，草稿答案原样保留。
            if (todo.status !== 'rejected') {
              return jsonResponse({ ok: false, code: 'NOT_REJECTED', error: '只有已拒绝的待办可以返回修改' }, 409)
            }
            todo.status = 'pending'
            todo.decidedAt = null
            persist()
            log('todo ' + todo.id + ' restored to pending')
            return jsonResponse({
              ok: true,
              id: todo.id,
              action,
              todo: summarizeTodo(todo),
              answers: todo.kind === 'question' && Array.isArray(todo.answers) ? todo.answers : null,
            })
          }
          if (action === 'reject') {
            if (todo.status === 'failed') {
              // 失败项没有“返回修改”语义：保持原有行为——记审批时间、通知来源会话、归档删除。
              todo.decidedAt = Date.now()
              const injected = notifyDecided(todo, 'reject')
              removeTodo(todo.id, 'failed')
              return jsonResponse({ ok: true, id: todo.id, action, archived: true, noticeInjected: injected })
            }
            if (todo.status !== 'pending') {
              return jsonResponse({ ok: false, code: 'NOT_REJECTABLE', error: '只有待审核或失败的待办可以拒绝' }, 409)
            }
            // 拒绝问答类待办时把用户当前草稿存进 todo.answers（宽松校验：允许没答完）。
            if (todo.kind === 'question' && body.answers !== undefined) {
              const draft = validateDraftAnswers(todo.questions, body.answers)
              if (draft.ok !== true) return jsonResponse({ ok: false, error: draft.error }, 400)
              todo.answers = draft.answers.length > 0 ? draft.answers : null
            }
            // 只置 rejected：不删除、不归档、不向来源会话注入「用户拒绝了待办」，
            // 因为用户可以「返回修改」，注入会让 AI 误以为这项已经被最终否决。
            todo.status = 'rejected'
            todo.decidedAt = Date.now()
            persist()
            log('todo ' + todo.id + ' rejected (kept for restore)')
            return jsonResponse({
              ok: true,
              id: todo.id,
              action,
              todo: summarizeTodo(todo),
              archived: false,
              noticeInjected: false,
            })
          }
          if (todo.status === 'rejected') {
            return jsonResponse({ ok: false, code: 'REJECTED', error: '该待办已被拒绝，请先“返回修改”' }, 409)
          }
          if (action === 'approve') {
            if (todo.reviewOnly === true) {
              return jsonResponse({ ok: false, code: 'REVIEW_ONLY', error: '该待办标记为仅复核（元工具不可重放），只能拒绝或删除' }, 409)
            }
            if (todo.kind !== 'approval') {
              return jsonResponse({ ok: false, error: '该待办是提问类型，请用 answer 提交答案' }, 400)
            }
            todo.status = 'approved'
            todo.decidedAt = Date.now()
            persist()
            const injected = notifyDecided(todo, 'approve')
            log('todo ' + todo.id + ' approved')
            return jsonResponse({ ok: true, id: todo.id, action, todo: summarizeTodo(todo), noticeInjected: injected })
          }
          // action === 'answer'
          if (todo.kind !== 'question') {
            return jsonResponse({ ok: false, error: '该待办是批准类型，请用 approve 处理' }, 400)
          }
          const validation = validateAnswers(todo.questions, body.answers)
          if (validation.ok !== true) {
            return jsonResponse({ ok: false, error: validation.error }, 400)
          }
          todo.status = 'approved'
          todo.answers = validation.answers
          todo.decidedAt = Date.now()
          persist()
          const injected = notifyDecided(todo, 'answer')
          log('todo ' + todo.id + ' answered')
          return jsonResponse({ ok: true, id: todo.id, action, todo: summarizeTodo(todo), noticeInjected: injected })
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: decide route')

    routeRegister({
      path: '/api/todo-inbox/apply',
      methods: ['POST'],
      requestBody: 'buffered',
      fetch: async (request) => {
        try {
          // 删除时机 1/2：用户点「应用操作」时，先把 rejected 条目归档删除。
          // 放在读取请求体之前：即使这次 apply 因参数/会话问题失败，清理也已经发生。
          purgeRejectedTodos()
          const body = await readJsonBody(request)
          const id = typeof body.id === 'string' ? body.id.trim() : ''
          if (id === '') return jsonResponse({ ok: false, error: 'id is required' }, 400)
          const todo = findTodo(id)
          if (todo === undefined) return jsonResponse({ ok: false, code: 'NOT_FOUND', error: '待办不存在或已被处理' }, 404)
          if (todo.status !== 'approved') {
            return jsonResponse({ ok: false, code: 'NOT_READY', error: '待办尚未批准/回答，请先处理' }, 409)
          }
          const agents = safeGet('agents')
          let agent
          try {
            agent = agents === undefined || typeof agents.get !== 'function' ? undefined : agents.get(todo.sessionId)
          } catch (error) {
            agent = undefined
          }
          if (agent === undefined || agent === null || typeof agent.followup !== 'function') {
            return jsonResponse({
              ok: false,
              code: 'SESSION_NOT_LIVE',
              error: '来源会话当前没有打开。请先在左侧会话列表打开/恢复该会话，再点击“应用操作”。',
            }, 409)
          }
          const text = todo.kind === 'question'
            ? '用户在待办收件箱回答了问题（待办 ' + todo.id + '）。请调用 todo_execute（参数 id=' + todo.id + '）取回答案并继续处理。'
            : '用户在待办收件箱点击了“应用操作”：请调用 todo_execute（参数 id=' + todo.id + '）执行待办对应的 ' +
              (todo.toolName ?? '原工具') + ' 一次。这是用户明确批准后的执行请求。'
          try {
            agent.followup({
              role: 'user',
              id: uuid(),
              content: [{ type: 'text', text }],
              source: { kind: 'todo-inbox', form: 'notice', summary: '待办执行请求' },
            })
          } catch (error) {
            return jsonResponse({ ok: false, code: 'FOLLOWUP_FAILED', error: '无法向来源会话发送消息：' + messageOf(error) }, 500)
          }
          log('apply request sent for todo ' + todo.id + ' to session ' + todo.sessionId)
          return jsonResponse({ ok: true, id: todo.id, sessionId: todo.sessionId, message: '已向来源会话发送执行请求。' })
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: apply route')

    routeRegister({
      path: '/api/todo-inbox/config',
      methods: ['GET', 'POST'],
      requestBody: 'buffered',
      fetch: async (request) => {
        try {
          const target = findConfigTarget()
          const editor = target.editor
          const entry = target.entry
          if (request.method === 'POST') {
            const body = await readJsonBody(request)
            const patch = {}
            if (body.autoEnqueue !== undefined) {
              if (typeof body.autoEnqueue !== 'boolean') {
                return jsonResponse({ ok: false, error: 'autoEnqueue must be a boolean' }, 400)
              }
              patch.autoEnqueue = body.autoEnqueue
            }
            if (body.pollIntervalMs !== undefined) {
              const poll = body.pollIntervalMs
              if (typeof poll !== 'number' || !Number.isSafeInteger(poll) || poll < 1000 || poll > 10000) {
                return jsonResponse({ ok: false, error: 'pollIntervalMs must be an integer between 1000 and 10000' }, 400)
              }
              patch.pollIntervalMs = poll
            }
            if (Object.keys(patch).length === 0) {
              return jsonResponse({ ok: false, error: 'provide autoEnqueue and/or pollIntervalMs' }, 400)
            }
            if (editor === undefined || typeof editor.edit !== 'function' || entry === undefined) {
              return jsonResponse({ ok: false, error: '当前 profile 不支持写回插件配置（configEditor 或配置行不可用）' }, 409)
            }
            try {
              await editor.edit(entry, (current) => Object.assign({}, current, patch))
            } catch (error) {
              log('config write failed:', messageOf(error))
              return jsonResponse({ ok: false, error: '写入配置失败：' + messageOf(error) }, 500)
            }
            return jsonResponse({
              ok: true,
              autoEnqueue: patch.autoEnqueue !== undefined ? patch.autoEnqueue : cfg.autoEnqueue,
              pollIntervalMs: patch.pollIntervalMs !== undefined ? patch.pollIntervalMs : cfg.pollIntervalMs,
            })
          }
          return jsonResponse({
            ok: true,
            autoEnqueue: cfg.autoEnqueue,
            pollIntervalMs: cfg.pollIntervalMs,
            maxTodos: cfg.maxTodos,
            writable: editor !== undefined && typeof editor.edit === 'function' && entry !== undefined,
          })
        } catch (error) {
          return jsonResponse({ ok: false, error: messageOf(error) }, 500)
        }
      },
    }, 'todo-inbox: config route')
  }

  try {
    ctx.inject(['connection'], registerRoutes)
  } catch (error) {
    log('route registration injection failed:', messageOf(error))
  }

  // ---------------------------------------------------------------------------
  // 卸载清理
  // ---------------------------------------------------------------------------
  ctx.effect(() => () => {
    grants.clear()
    log('host disposed; ' + todos.length + ' todo(s) retained on disk')
  }, 'todo-inbox: cleanup')

  log('host active — autoEnqueue=' + cfg.autoEnqueue + ', pollIntervalMs=' + cfg.pollIntervalMs +
    ', todos=' + todos.length + ', home=' + home)
}
